def _ensure_template():
    import os, base64, gzip
    path = '/tmp/TEMPLATE_HSA_PATRIMON_IA.pptx'
    if not os.path.exists(path):
        raw = gzip.decompress(base64.b64decode(_TEMPLATE_B64_GZ))
        with open(path, 'wb') as f:
            f.write(raw)
    return path

REF_TEMPLATE = _ensure_template()

