# ════════════════════════════════════════════════════════════════════════════
# DATA AGGREGATION — works for any client
# ════════════════════════════════════════════════════════════════════════════
def aggregate(data):
    """Returns dict with everything the deck needs."""
    groups = data.get('groups', [])

    # For the PPT slide 2 we have at most 6 callout slots around the pie.
    # Strategy: if the client has ≤ 6 categories, each gets its own slice
    # (so Cripto / Previdência / Equity show up as their own slices when
    # the client has them). If there are MORE than 6 categories, keep the
    # 5 largest as their own slices and bundle the remaining (smaller)
    # ones into a single "Outros" slice. The Outros label is decorated
    # with the bundled categories when 2-3 of them so the reader knows
    # what's inside (e.g. "Outros (Cripto + Equity)").

    # Short forms used in the Outros bucket label (keeps it readable
    # against the narrow callout width).
    _SHORT = {
        'Criptoativos': 'Cripto',
        'Previdência Privada': 'Previdência',
        'Remuneração Variável em Equity': 'Equity',
        'Bens Imóveis': 'Imóveis',
        'Bens Móveis': 'Móveis',
        'Bens Móveis / Veículos / Arte': 'Móveis',
        'Participações Societárias': 'Part. Soc.',
        'Aplicações e Investimentos': 'Aplicações',
        'Créditos e Direitos': 'Créditos',
        'Contas Bancárias e Saldos': 'Contas',
        'Contas Bancárias': 'Contas',
    }

    def _top6_with_outros(agg_dict):
        """agg_dict: {category_name: total_value}. Returns:
          - items: list of (name, value) tuples (≤ 6 entries)
          - components: dict mapping "Outros (...)" label → list of the
            original category names bundled inside it (empty dict if no
            bundling happened).
        Used to drive both the pie chart and the strategy-hyperlink lookup
        for the Outros callout."""
        items = sorted(agg_dict.items(), key=lambda kv: -kv[1])
        if len(items) <= 6:
            return items, {}
        top5 = items[:5]
        rest = items[5:]
        rest_total = sum(v for _, v in rest)
        # Always show the bundled category names — transparency beats the
        # vague generic "Outros" even when 4+ categories are bundled.
        # Short names (via _SHORT lookup) keep the label compact.
        names = [_SHORT.get(n, n) for n, _ in rest]
        outros_label = f"Outros ({' + '.join(names)})"
        components = {outros_label: [n for n, _ in rest]}
        return top5 + [(outros_label, rest_total)], components

    # Brasil: sum dirpf per group-name (no forced bucketing — each category
    # keeps its own name; bundling into "Outros" only happens if > 6 total).
    br_agg = {}
    for g in groups:
        if g.get('jurisdiction') == 'Brasil':
            tot = sum((it.get('dirpf') or 0) for it in g['items'])
            br_agg[g['name']] = br_agg.get(g['name'], 0) + tot
    br_sorted, br_outros_components = _top6_with_outros(br_agg)

    # Offshore: same logic, summing dcbe.
    off_agg = {}
    for g in groups:
        if g.get('jurisdiction') == 'Offshore':
            tot = sum((it.get('dcbe') or 0) for it in g['items'])
            off_agg[g['name']] = off_agg.get(g['name'], 0) + tot
    off_sorted, off_outros_components = _top6_with_outros(off_agg)

    total_br  = sum(v for _, v in br_sorted)
    total_off = sum(v for _, v in off_sorted)

    return {
        'client':    data.get('client', '—'),
        'year':      data.get('year', ''),
        'spouse':    data.get('spouse') or {},
        'dependents':data.get('dependents') or [],
        'br_sorted': br_sorted,
        'off_sorted':off_sorted,
        'total_br':  total_br,
        'total_off': total_off,
        # When a slide-2 callout aggregates multiple categories into an
        # "Outros" bucket, the hyperlinks shown under that callout should
        # pool the strategies of the bundled categories. This dict maps
        # "Outros (...)" label → list of underlying category names.
        'br_outros_components':  br_outros_components,
        'off_outros_components': off_outros_components,
    }

def brl(v, d=1): return f"R$ {v/1e6:.{d}f}M"
def usd(v, d=1): return f"US$ {v/1e6:.{d}f}M"

# ════════════════════════════════════════════════════════════════════════════
# STAGE 1 — strip orphan slides + dead comments/authors from REF
# The Carol G template carries modern-comments that reference deleted slide
# IDs (583, 586) plus an authors.xml — PowerPoint chokes on these. Remove all.
# ════════════════════════════════════════════════════════════════════════════
def strip_orphans(path):
    tmp = tempfile.mkdtemp()
    with zipfile.ZipFile(path, 'r') as z:
        z.extractall(tmp)

    # ── 1. orphan slides (in rels but not in sldIdLst) ──────────────────────
    with open(os.path.join(tmp,'ppt/presentation.xml'),'r',encoding='utf-8') as f:
        pres = f.read()
    used = set(re.findall(r'r:id="(rId\d+)"',
        re.search(r'<p:sldIdLst>.*?</p:sldIdLst>', pres, re.DOTALL).group(0)))

    rels_path = os.path.join(tmp,'ppt/_rels/presentation.xml.rels')
    with open(rels_path,'r',encoding='utf-8') as f:
        pr = f.read()
    orphans = set()
    for r in re.findall(r'<Relationship\b[^>]*?/>', pr):
        rid = re.search(r'Id="(rId\d+)"', r)
        tgt = re.search(r'Target="([^"]+)"', r)
        if rid and tgt and tgt.group(1).startswith('slides/'):
            if rid.group(1) not in used:
                orphans.add('ppt/'+tgt.group(1))
                pr = pr.replace(r, '')
    # also drop comment/author rels from presentation.xml.rels
    pr = re.sub(r'<Relationship[^>]*(?:omment|author)[^>]*/>', '', pr)
    with open(rels_path,'w',encoding='utf-8') as f:
        f.write(pr)

    for sf in orphans:
        for p in [os.path.join(tmp,sf),
                  os.path.join(tmp, sf.replace('slides/','slides/_rels/')+'.rels')]:
            if os.path.exists(p): os.remove(p)

    # ── 2. remove ALL comments + authors (reference dead slide IDs) ─────────
    comments_dir = os.path.join(tmp,'ppt/comments')
    if os.path.isdir(comments_dir):
        shutil.rmtree(comments_dir)
    authors_p = os.path.join(tmp,'ppt/authors.xml')
    if os.path.exists(authors_p):
        os.remove(authors_p)

    # ── 3. strip comment/author rels from every slide's .rels ───────────────
    slide_rels_dir = os.path.join(tmp,'ppt/slides/_rels')
    if os.path.isdir(slide_rels_dir):
        for fn in os.listdir(slide_rels_dir):
            fp = os.path.join(slide_rels_dir, fn)
            with open(fp,'r',encoding='utf-8') as f:
                c = f.read()
            new_c = re.sub(r'<Relationship[^>]*(?:omment|author)[^>]*/>', '', c)
            if new_c != c:
                with open(fp,'w',encoding='utf-8') as f:
                    f.write(new_c)

    # ── 3b. CRITICAL: remove <p:ext> commentRel blocks from slide XMLs ──────
    # The slide bodies carry <p:ext><p188:commentRel r:id="rIdN"/></p:ext>.
    # Once the rels entry is gone, this becomes a dangling reference that
    # makes PowerPoint reject the whole file. Strip the ext block too.
    slides_dir = os.path.join(tmp,'ppt/slides')
    if os.path.isdir(slides_dir):
        for fn in os.listdir(slides_dir):
            if not fn.endswith('.xml'): continue
            fp = os.path.join(slides_dir, fn)
            with open(fp,'r',encoding='utf-8') as f:
                c = f.read()
            new_c = re.sub(
                r'<p:ext\b[^>]*>(?:(?!</p:ext>).)*?commentRel.*?</p:ext>',
                '', c, flags=re.DOTALL)
            if new_c != c:
                with open(fp,'w',encoding='utf-8') as f:
                    f.write(new_c)

    # ── 4. clean [Content_Types].xml ────────────────────────────────────────
    ct_path = os.path.join(tmp,'[Content_Types].xml')
    with open(ct_path,'r',encoding='utf-8') as f:
        ct = f.read()
    for sf in orphans:
        ct = re.sub(rf'<Override PartName="/{re.escape(sf)}"[^/]*/>', '', ct)
    ct = re.sub(r'<Override PartName="[^"]*omment[^"]*"[^/]*/>', '', ct)
    ct = re.sub(r'<Override PartName="[^"]*author[^"]*"[^/]*/>', '', ct)
    with open(ct_path,'w',encoding='utf-8') as f:
        f.write(ct)

    out = path + '.tmp'
    with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as zout:
        for root,_,files in os.walk(tmp):
            for f in files:
                fp = os.path.join(root,f)
                zout.write(fp, os.path.relpath(fp,tmp))
    shutil.rmtree(tmp)
    os.replace(out, path)

# ════════════════════════════════════════════════════════════════════════════
# STAGE 4 — XML post-process: chart fonts + pie color
# ════════════════════════════════════════════════════════════════════════════
def patch_xml(path):
    """Force Gotham SSm Bold on all chart text. Uses lxml so the injected
    <a:latin> lands in the schema-correct position (after fill, before ea/cs).
    Putting it anywhere else makes PowerPoint reject the file."""
    tmp = tempfile.mkdtemp()
    with zipfile.ZipFile(path,'r') as z:
        z.extractall(tmp)

    GOTHAM = 'Gotham SSm Bold'
    A = 'http://schemas.openxmlformats.org/drawingml/2006/main'
    nsA = '{%s}' % A

    # CT_TextCharacterProperties child order (the elements that can precede
    # <a:latin>). <a:latin> must be inserted *after* the last of these that
    # is present, and *before* ea/cs/sym/hlink*/rtl/extLst.
    BEFORE_LATIN = ['ln','noFill','solidFill','gradFill','blipFill','pattFill',
                    'grpFill','effectLst','effectDag','highlight','uLnTx','uLn',
                    'uFillTx','uFill']
    AFTER_LATIN  = ['ea','cs','sym','hlinkClick','hlinkMouseOver','rtl','extLst']

    def fix_rpr(el):
        """Ensure el (rPr/defRPr/endParaRPr) has <a:latin typeface=GOTHAM>
        in the schema-correct slot."""
        latin = el.find(nsA+'latin')
        if latin is not None:
            latin.set('typeface', GOTHAM)
            # also normalise ea/cs if present
            for tag in ('ea','cs'):
                e = el.find(nsA+tag)
                if e is not None:
                    e.set('typeface', GOTHAM)
            return
        # need to insert a new <a:latin>
        latin = etree.Element(nsA+'latin')
        latin.set('typeface', GOTHAM)
        # find insertion index: after last BEFORE_LATIN child
        children = list(el)
        insert_at = 0
        for i, child in enumerate(children):
            tag = etree.QName(child).localname
            if tag in BEFORE_LATIN:
                insert_at = i + 1
            elif tag in AFTER_LATIN:
                insert_at = i
                break
        el.insert(insert_at, latin)

    # Category axis = the labels listed beside the horizontal bars.
    # chart2 (slide 3) has them at sz=900; chart7/8 (slide 4) have no txPr
    # at all so they inherit a large default. Force a small size on every
    # category axis. CT_CatAx child order: ...tickLblPos, spPr, txPr, crossAx...
    nsC = '{http://schemas.openxmlformats.org/drawingml/2006/chart}'
    CAT_SZ = '700'   # ~7pt — small, tidy labels beside the bars
    CATAX_BEFORE_TXPR = ['axId','scaling','delete','axPos','majorGridlines',
        'minorGridlines','title','numFmt','majorTickMark','minorTickMark',
        'tickLblPos','spPr']
    def shrink_cat_axis(root):
        for catax in root.iter(nsC+'catAx'):
            txpr = catax.find(nsC+'txPr')
            if txpr is not None:
                # already has txPr — just shrink every defRPr/rPr size
                for tag in ('defRPr','rPr','endParaRPr'):
                    for el in txpr.iter(nsA+tag):
                        el.set('sz', CAT_SZ)
            else:
                # build a minimal txPr and insert it in schema-correct slot
                txpr = etree.SubElement(catax, nsC+'txPr')
                etree.SubElement(txpr, nsA+'bodyPr')
                etree.SubElement(txpr, nsA+'lstStyle')
                p = etree.SubElement(txpr, nsA+'p')
                ppr = etree.SubElement(p, nsA+'pPr')
                defrpr = etree.SubElement(ppr, nsA+'defRPr')
                defrpr.set('sz', CAT_SZ)
                etree.SubElement(p, nsA+'endParaRPr')
                # move txpr into correct position (before crossAx)
                catax.remove(txpr)
                kids = list(catax)
                insert_at = len(kids)
                for i, child in enumerate(kids):
                    tag = etree.QName(child).localname
                    if tag not in CATAX_BEFORE_TXPR:
                        insert_at = i
                        break
                catax.insert(insert_at, txpr)

    # Bar charts in this template render thin bars floating far from their
    # category labels. Two fixes per bar chart:
    #   1. gapWidth → 30  (gap is only 30% of bar thickness → fat, solid bars)
    #   2. tighten the plotArea manualLayout: the 7pt category labels need
    #      only a slim left margin, so pull the plot region left and let it
    #      run wide — bars then sit right next to their labels.
    # CT_PlotArea child order: layout, (chart...), (axes...), dTable, spPr.
    def fix_bar_geometry(root):
        bar_charts = list(root.iter(nsC+'barChart'))
        if not bar_charts:
            return
        for bc in bar_charts:
            # gapWidth: smaller = fatter bars. 30 = bars nearly touching.
            gw = bc.find(nsC+'gapWidth')
            if gw is not None:
                gw.set('val', '30')
            else:
                gw = etree.Element(nsC+'gapWidth'); gw.set('val', '30')
                kids = list(bc)
                insert_at = len(kids)
                for i, child in enumerate(kids):
                    if etree.QName(child).localname == 'axId':
                        insert_at = i; break
                bc.insert(insert_at, gw)
        # tighten the plot area via manualLayout
        for pa in root.iter(nsC+'plotArea'):
            layout = pa.find(nsC+'layout')
            if layout is None:
                layout = etree.Element(nsC+'layout')
                pa.insert(0, layout)
            for ml in layout.findall(nsC+'manualLayout'):
                layout.remove(ml)
            ml = etree.SubElement(layout, nsC+'manualLayout')
            def _sub(tag, val):
                e = etree.SubElement(ml, nsC+tag); e.set('val', val)
            _sub('layoutTarget', 'inner')
            _sub('xMode', 'edge'); _sub('yMode', 'edge')
            # x: only 13% left margin — just enough for the 7pt labels, so
            #    bars start right next to their text instead of floating.
            # w: 84% wide · y: 5% from top · h: 88% tall
            _sub('x', '0.13'); _sub('y', '0.05')
            _sub('w', '0.84'); _sub('h', '0.88')

    charts_dir = os.path.join(tmp,'ppt/charts')
    if os.path.isdir(charts_dir):
        for fn in os.listdir(charts_dir):
            if not fn.endswith('.xml'): continue
            fp = os.path.join(charts_dir, fn)
            tree = etree.parse(fp)
            root = tree.getroot()
            # fix every rPr / defRPr / endParaRPr in the chart
            for tag in ('rPr','defRPr','endParaRPr'):
                for el in root.iter(nsA+tag):
                    fix_rpr(el)
            # shrink the category-axis labels (the titles beside the bars)
            shrink_cat_axis(root)
            # fatter bars + plot area pulled next to the labels
            fix_bar_geometry(root)
            # pie chart: recolor stray lime slice → grey
            xml_bytes = etree.tostring(tree, xml_declaration=True,
                                       encoding='UTF-8', standalone=True)
            if fn == 'chart1.xml':
                xml_bytes = xml_bytes.replace(b'val="E3E520"', b'val="5C6770"')
            with open(fp,'wb') as f:
                f.write(xml_bytes)

    out = path + '.tmp'
    with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as zout:
        for root,_,files in os.walk(tmp):
            for f in files:
                fp = os.path.join(root,f)
                zout.write(fp, os.path.relpath(fp,tmp))
    shutil.rmtree(tmp)
    os.replace(out, path)

# ════════════════════════════════════════════════════════════════════════════
# Chart color rebuild — fixes dPt/category count mismatch
# After replace_data() the template's 6 dPt no longer match N categories,
# so renderers fall back to auto-colors. Solution: wipe dPt, re-add exactly N.
# ════════════════════════════════════════════════════════════════════════════
def recolor_chart(chart, palette):
    """Remove all dPt, re-add exactly one per category with palette colors."""
    for plot in chart.plots:
        for series in plot.series:
            ser_el = series._element
            for dpt in ser_el.findall(qn('c:dPt')):
                ser_el.remove(dpt)
            for i, pt in enumerate(series.points):
                pt.format.fill.solid()
                pt.format.fill.fore_color.rgb = RGBColor.from_string(
                    palette[i % len(palette)])

# ════════════════════════════════════════════════════════════════════════════
# Shape helpers for slides 5-6
# ════════════════════════════════════════════════════════════════════════════
KEEP = {"Picture 10","Picture 2","TextBox 13","Text Box65","Text Box62","Text 7"}

def _y(el):
    for x in el.iter():
        if x.tag.endswith('}xfrm'):
            o = x.find('{http://schemas.openxmlformats.org/drawingml/2006/main}off')
            if o is not None:
                try: return int(o.get('y',0))
                except: pass
    return 0

def clear(sl):
    sp = sl.shapes._spTree
    rm = []
    for el in list(sp):
        nm=''
        for s in el.iter():
            if s.tag.endswith('cNvPr'): nm=s.get('name',''); break
        if not nm: continue
        if nm not in KEEP: rm.append(el)
        elif nm=='Picture 10' and _y(el)<6_000_000: rm.append(el)
    for el in rm:
        p=el.getparent()
        if p is not None: p.remove(el)

def nln(sh):
    spPr = sh.element.find(qn('p:spPr'))
    ln = etree.SubElement(spPr, qn('a:ln')); etree.SubElement(ln, qn('a:noFill'))

def R(sl,l,t,w,h,fill=None,lc=None,lw=0.75):
    sh = sl.shapes.add_shape(MSO_SHAPE.RECTANGLE,Emu(l),Emu(t),Emu(w),Emu(h))
    if fill: sh.fill.solid(); sh.fill.fore_color.rgb=fill
    else: sh.fill.background()
    if lc: sh.line.color.rgb=lc; sh.line.width=Pt(lw)
    else: nln(sh)
    return sh

def O(sl,l,t,w,h,fill=None):
    sh = sl.shapes.add_shape(MSO_SHAPE.OVAL,Emu(l),Emu(t),Emu(w),Emu(h))
    if fill: sh.fill.solid(); sh.fill.fore_color.rgb=fill
    else: sh.fill.background()
    nln(sh); return sh

def DIA(sl,l,t,w,h,fill=None):
    sh = sl.shapes.add_shape(MSO_SHAPE.DIAMOND,Emu(l),Emu(t),Emu(w),Emu(h))
    if fill: sh.fill.solid(); sh.fill.fore_color.rgb=fill
    else: sh.fill.background()
    nln(sh); return sh

def T(sl,text,l,t,w,h,pt,bold=False,col=None,align='left',
      font='Gotham SSm Book',wrap=False):
    box = sl.shapes.add_textbox(Emu(l),Emu(t),Emu(w),Emu(h))
    tf=box.text_frame; tf.word_wrap=wrap
    p=tf.paragraphs[0]
    p.alignment={'left':PP_ALIGN.LEFT,'center':PP_ALIGN.CENTER,'right':PP_ALIGN.RIGHT}[align]
    r=p.add_run(); r.text=text
    r.font.size=Pt(pt); r.font.bold=bold; r.font.name=font
    if col: r.font.color.rgb=col
    return box

def L(sl,x1,y1,x2,y2,col=None,w=0.75):
    c=sl.shapes.add_connector(MSO_CONNECTOR_TYPE.STRAIGHT,Emu(x1),Emu(y1),Emu(x2),Emu(y2))
    c.line.color.rgb=col or GRAY_MED; c.line.width=Pt(w)

def _outline(sh, col, lw=1.4):
    """Make a shape an unfilled outline in the given colour."""
    sh.fill.background()
    sh.line.color.rgb = col
    sh.line.width = Pt(lw)

def Person(sl, cx, cy, sz=300_000, col=None, gender=None):
    """Clean person icon: circle head + body silhouette, drawn as solid
    shapes. cx,cy is the icon's centre.

    gender:
      'F' → classic female pictogram: round head + a triangular 'dress'
            body that flares wide at the hem (the universal restroom-sign
            woman). Instantly distinguishable from the male icon.
      'M' or None → round head + straight-shouldered bust silhouette.

    Both styles use the same head size and overall footprint so they sit
    consistently in the org-chart boxes.
    """
    c = col or NAVY
    top = cy - sz // 2
    bottom = cy + sz // 2

    def _freeform(points):
        fb = sl.shapes.build_freeform(Emu(points[0][0]), Emu(points[0][1]))
        fb.add_line_segments([(Emu(x), Emu(y)) for x, y in points[1:]],
                             close=True)
        sh = fb.convert_to_shape()
        sh.fill.solid(); sh.fill.fore_color.rgb = c
        sh.line.color.rgb = c; sh.line.width = Pt(0.5)
        return sh

    if gender == 'F':
        # ── female: round head + triangular dress ────────────────────────
        head_d = int(sz * 0.44)
        head_x = cx - head_d // 2
        head_y = top
        head = sl.shapes.add_shape(MSO_SHAPE.OVAL,
            Emu(head_x), Emu(head_y), Emu(head_d), Emu(head_d))
        head.fill.solid(); head.fill.fore_color.rgb = c
        head.line.color.rgb = c; head.line.width = Pt(0.5)

        # dress: narrow at the shoulders, flaring out to a wide hem
        body_top  = head_y + head_d + int(sz * 0.04)
        neck_half = int(sz * 0.13)
        hem_half  = int(sz * 0.42)
        _freeform([
            (cx - neck_half, body_top),       # left shoulder
            (cx + neck_half, body_top),       # right shoulder
            (cx + hem_half,  bottom),         # hem right
            (cx - hem_half,  bottom),         # hem left
        ])
    else:
        # ── male: round head + straight-shouldered bust ──────────────────
        head_d = int(sz * 0.46)
        head_x = cx - head_d // 2
        head_y = top
        head = sl.shapes.add_shape(MSO_SHAPE.OVAL,
            Emu(head_x), Emu(head_y), Emu(head_d), Emu(head_d))
        head.fill.solid(); head.fill.fore_color.rgb = c
        head.line.color.rgb = c; head.line.width = Pt(0.5)

        bust_top  = head_y + head_d + int(sz * 0.04)
        half      = int(sz * 0.49)
        neck_half = int(sz * 0.16)
        _freeform([
            (cx - neck_half,            bust_top),
            (cx + int(neck_half*0.4),   bust_top - int(sz*0.005)),
            (cx + int(half*0.55),       bust_top + int(sz*0.10)),
            (cx + half - int(sz*0.02),  bust_top + int(sz*0.26)),
            (cx + half,                 bust_top + int(sz*0.42)),
            (cx + half,                 bottom),
            (cx - half,                 bottom),
            (cx - half,                 bust_top + int(sz*0.42)),
            (cx - half + int(sz*0.02),  bust_top + int(sz*0.26)),
            (cx - int(half*0.55),       bust_top + int(sz*0.10)),
            (cx - int(neck_half*0.4),   bust_top - int(sz*0.005)),
        ])

def guess_gender(name):
    """Best-effort gender guess from a Brazilian first name. Returns 'F',
    'M', or None. Used only to pick the icon style — purely cosmetic, and
    callers can always pass an explicit gender to override."""
    if not name:
        return None
    first = name.strip().split()[0].lower()
    import unicodedata
    first = ''.join(ch for ch in unicodedata.normalize('NFD', first)
                    if unicodedata.category(ch) != 'Mn')
    female_names = {
        'maria','ana','beatriz','julia','juliana','mariana','fernanda',
        'patricia','camila','leticia','larissa','gabriela','amanda',
        'carla','sandra','sonia','silvia','lucia','luiza','luisa','sofia',
        'isabela','isabel','helena','laura','clara','alice','valentina',
        'manuela','heloisa','livia','antonia','adriana','renata','vanessa',
        'cristina','simone','tatiana','priscila','bruna','carolina','carol',
        'debora','daniela','rafaela','viviane','elaine','rosana','rosa',
        'teresa','tereza','angela','monica','marcia','regina','eliane',
        'denise','aline','jessica','natalia','barbara','bianca','raquel',
        'flavia','claudia','sabrina','michele','michelle','andrea','andreia',
        'francisca','vera','marta','marlene','neusa','ines','irene','edna',
    }
    male_names = {
        'jose','joao','antonio','francisco','carlos','paulo','pedro','lucas',
        'luiz','luis','marcos','marco','gabriel','rafael','daniel','marcelo',
        'bruno','eduardo','felipe','filipe','rodrigo','sergio','fernando',
        'roberto','ricardo','andre','fabio','alexandre','leonardo','gustavo',
        'mateus','matheus','guilherme','vinicius','thiago','tiago','diego',
        'henrique','arthur','miguel','davi','heitor','bernardo',
        'samuel','enzo','nicolas','vitor','victor','caio','renato','julio',
        'cesar','claudio','wilson','wagner','edson','adriano','alan','alex',
        'jorge','raimundo','sebastiao','geraldo','manoel','manuel','osvaldo',
        'valdir','nelson','wesley','william','douglas','anderson','jefferson',
    }
    if first in female_names:
        return 'F'
    if first in male_names:
        return 'M'
    if first.endswith('a'):
        return 'F'
    if first.endswith(('o','r','l','n','s','m')):
        return 'M'
    return None

def brazil_flag(sl,cx,cy,w=300_000):
    """Draw a small Brazil flag centred at (cx,cy)."""
    h = int(w*0.70)
    l = cx - w//2; t = cy - h//2
    R(sl, l, t, w, h, fill=BR_GREEN)
    # yellow rhombus inset
    dia_w = int(w*0.74); dia_h = int(h*0.74)
    DIA(sl, cx-dia_w//2, cy-dia_h//2, dia_w, dia_h, fill=BR_YELLOW)
    # blue circle
    cir = int(h*0.40)
    O(sl, cx-cir//2, cy-cir//2, cir, cir, fill=BR_BLUE)

# ════════════════════════════════════════════════════════════════════════════
# ASSET ICONS — simple monochrome vector icons drawn from MSO primitives.
# All icons fit roughly within a sz×sz box centred at (cx,cy), in NAVY.
# ════════════════════════════════════════════════════════════════════════════
from pptx.enum.shapes import MSO_SHAPE as _MS

def _ish(sl, shape, l, t, w, h, fill=None, no_line=True):
    sh = sl.shapes.add_shape(shape, Emu(int(l)), Emu(int(t)), Emu(int(w)), Emu(int(h)))
    if fill is not None:
        sh.fill.solid(); sh.fill.fore_color.rgb = fill
    else:
        sh.fill.background()
    if no_line:
        sh.line.fill.background()
    return sh

def icon_house(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    h = sz; w = sz
    body_h = int(h*0.55); body_w = int(w*0.78)
    body_top = cy + h//2 - body_h
    _ish(sl, _MS.RECTANGLE, cx-body_w//2, body_top, body_w, body_h, fill=col)
    roof_w = int(body_w*1.18); roof_h = h - body_h
    _ish(sl, _MS.ISOSCELES_TRIANGLE, cx-roof_w//2, cy-h//2, roof_w, roof_h+30_000, fill=col)
    # white door
    dw = int(body_w*0.26); dh = int(body_h*0.50)
    _ish(sl, _MS.RECTANGLE, cx-dw//2, body_top+body_h-dh, dw, dh, fill=WHITE)

def icon_building(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    w = int(sz*0.72); h = int(sz*1.05)
    l = cx-w//2; t = cy-h//2
    _ish(sl, _MS.RECTANGLE, l, t, w, h, fill=col)
    cols, rows = 3, 4
    pad = int(min(w,h)*0.12)
    aw = w - 2*pad; ah = h - 2*pad
    gx = int(aw*0.12); gy = int(ah*0.10)
    ww = (aw - (cols-1)*gx) // cols
    wh = (ah - (rows-1)*gy) // rows
    for r in range(rows):
        for c in range(cols):
            _ish(sl, _MS.RECTANGLE, l+pad+c*(ww+gx), t+pad+r*(wh+gy), ww, wh, fill=WHITE)

def icon_bank(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    w = sz; h = int(sz*0.88)
    l = cx-w//2; t = cy-h//2
    # pediment
    ph = int(h*0.22)
    _ish(sl, _MS.ISOSCELES_TRIANGLE, l, t, w, ph, fill=col)
    # architrave
    ah = int(h*0.10)
    _ish(sl, _MS.RECTANGLE, l, t+ph, w, ah, fill=col)
    # base
    bh = int(h*0.13)
    by = t+h-bh
    _ish(sl, _MS.RECTANGLE, l, by, w, bh, fill=col)
    # columns
    col_top = t+ph+ah+20_000
    col_bot = by-20_000
    col_h = col_bot-col_top
    n = 4
    caw = int(w*0.78)
    cal = cx-caw//2
    gap = int(caw*0.05)
    cw = (caw-(n-1)*gap)//n
    for i in range(n):
        _ish(sl, _MS.RECTANGLE, cal+i*(cw+gap), col_top, cw, col_h, fill=col)

def icon_chart(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    w = sz; h = int(sz*0.88)
    l = cx-w//2; base_y = cy+h//2
    n = 4; gap = int(w*0.07)
    bw = (w-(n-1)*gap)//n
    for i in range(n):
        bh = int(h*(0.32 + 0.21*i))
        _ish(sl, _MS.RECTANGLE, l+i*(bw+gap), base_y-bh, bw, bh, fill=col)

def icon_coin(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    d = int(sz*0.92)
    _ish(sl, _MS.OVAL, cx-d//2, cy-d//2, d, d, fill=col)
    # white $ char
    T(sl,'$',cx-d//2, cy-d//2+5_000, d, d,
      pt=int(sz/14_000), bold=True, col=WHITE, align='center', font='Gotham SSm Bold')

def icon_doc(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    w = int(sz*0.74); h = int(sz*1.0)
    l = cx-w//2; t = cy-h//2
    _ish(sl, _MS.RECTANGLE, l, t, w, h, fill=col)
    # 4 horizontal "lines" inside, white
    pad = int(h*0.20)
    avail_h = h - 2*pad
    n = 4; spacing = avail_h // (n+1)
    for i in range(n):
        y = t + pad + (i+1)*spacing - 9_000
        lw = int(w * (0.62 if i==n-1 else 0.72))
        _ish(sl, _MS.RECTANGLE, cx-lw//2, y, lw, 18_000, fill=WHITE)

def icon_frame(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    w = sz; h = int(sz*0.88)
    l = cx-w//2; t = cy-h//2
    # outer (frame)
    _ish(sl, _MS.RECTANGLE, l, t, w, h, fill=col)
    pad = int(min(w,h)*0.14)
    # inner white (canvas)
    _ish(sl, _MS.RECTANGLE, l+pad, t+pad, w-2*pad, h-2*pad, fill=WHITE)
    # small "mountain" inside
    mh = int((h-2*pad)*0.55)
    _ish(sl, _MS.ISOSCELES_TRIANGLE,
         l+pad+int((w-2*pad)*0.20),
         t+pad+(h-2*pad)-mh,
         int((w-2*pad)*0.60), mh, fill=col)

def icon_shield(sl, cx, cy, sz=200_000, col=None):
    col = col or NAVY
    w = int(sz*0.78); h = sz
    # PENTAGON shape (5-sided, points up) — used as shield. HOME_PLATE was
    # the prior choice but it's missing in some python-pptx builds. Pentagon
    # is universally available and reads as a shield/badge.
    _ish(sl, _MS.PENTAGON, cx-w//2, cy-h//2, w, h, fill=col)
    # tiny white check
    T(sl,'✓',cx-w//2, cy-h//2+15_000, w, h,
      pt=int(sz/13_000), bold=True, col=WHITE, align='center', font='Gotham SSm Bold')

def icon_globe(sl, cx, cy, sz=180_000, col=None):
    col = col or NAVY
    d = sz
    _ish(sl, _MS.OVAL, cx-d//2, cy-d//2, d, d, fill=col)
    # white horizontal equator
    eh = int(d*0.07)
    _ish(sl, _MS.RECTANGLE, cx-d//2, cy-eh//2, d, eh, fill=WHITE)
    # white vertical meridian
    vw = int(d*0.07)
    _ish(sl, _MS.RECTANGLE, cx-vw//2, cy-d//2, vw, d, fill=WHITE)

def icon_for(name):
    """Map asset-group name → icon-draw function."""
    n = (name or '').lower()
    if 'ociet' in n or 'capital' in n: return icon_building
    if 'imóvei' in n or 'imovei' in n: return icon_house
    if 'aplicaç' in n or 'aplicac' in n or 'investiment' in n: return icon_chart
    if 'banc' in n or 'depósit' in n or 'deposit' in n or 'conta' in n: return icon_bank
    if 'crédit' in n or 'credit' in n or 'direit' in n: return icon_coin
    if 'arte' in n or 'obra' in n or 'móvei' in n or 'movei' in n: return icon_frame
    if 'seguro' in n: return icon_shield
    return icon_doc   # fallback: "Outros"

def ribbon(sl,title):
    for sh in sl.shapes:
        if sh.name=='Text 7':
            tf=sh.text_frame; tf.clear()
            p=tf.paragraphs[0]; p.alignment=PP_ALIGN.LEFT
            r=p.add_run(); r.text=title
            r.font.size=Pt(11); r.font.bold=True
            r.font.name='Gotham SSm Bold'; r.font.color.rgb=NAVY
            break

def add_title_bar(sl):
    """HSA-style filled yellow rectangle behind the slide title (Text 7).
    Positioned at L=0, T=1076580, W=5896800, H=261600 to match the HSA ref
    template. Title text sits on top via z-order re-stacking."""
    from pptx.enum.shapes import MSO_SHAPE
    # Add the bar
    bar = sl.shapes.add_shape(MSO_SHAPE.RECTANGLE,
                              Emu(0), Emu(1_076_580),
                              Emu(5_896_800), Emu(261_600))
    bar.fill.solid()
    bar.fill.fore_color.rgb = LIME
    bar.line.fill.background()
    # Re-order: move Text 7 to the end of spTree so it renders on top
    sp_tree = sl.shapes._spTree
    text7_el = None
    for el in list(sp_tree):
        for child in el.iter():
            if child.tag.endswith('cNvPr') and child.get('name','') == 'Text 7':
                text7_el = el
                break
        if text7_el is not None: break
    if text7_el is not None:
        sp_tree.remove(text7_el)
        sp_tree.append(text7_el)
    # Vertically centre the title on the bar
    BAR_MID = 1_076_580 + 261_600 // 2
    for sh in sl.shapes:
        if sh.name == 'Text 7':
            sh.top = Emu(BAR_MID - 347_472 // 2)
            sh.height = Emu(347_472)
            break

def kill_ghost_text7(sl):
    """Carol G's template has a 2nd 'Text 7' shape on slides 3 & 4 — a leftover
    Calibri label ('BRASIL' / 'TOTAL ATIVOS') that floats behind the real
    headers. ribbon() only edits the first; this removes every extra one."""
    sp = sl.shapes._spTree
    seen_first = False
    for el in list(sp):
        nm = ''
        for s in el.iter():
            if s.tag.endswith('cNvPr'): nm = s.get('name',''); break
        if nm == 'Text 7':
            if seen_first:
                p = el.getparent()
                if p is not None: p.remove(el)
            else:
                seen_first = True

def force_font_gotham(sh, size_pt=None, bold=True, color=None):
    """Force Gotham SSm Bold on every run in a shape (template textboxes
    inherit Calibri because they have no explicit <a:latin>)."""
    if not hasattr(sh, 'text_frame'):
        return
    for para in sh.text_frame.paragraphs:
        for run in para.runs:
            run.font.name = 'Gotham SSm Bold'
            run.font.bold = bold
            if size_pt is not None:
                run.font.size = Pt(size_pt)
            if color is not None:
                run.font.color.rgb = color

def fh(pt): return int(pt*12700*1.85)

