def short_strategy(s, max_len=42):
    """Truncate long strategy names for callout display."""
    s = s.split(" (")[0]   # strip parenthetical detail
    if len(s) > max_len:
        s = s[:max_len] + "…"
    return s


def _draw_redesigned_slide2(sl, prs_w, prs_h, sorted_items, total,
                            indice_p, indice_s, strategy_slides,
                            outros_components=None,
                            jurisdiction='Brasil'):
    """Draw the redesigned slide 2 (or 3): donut centered + up to 6 callouts
    around it with category name, value, percentage, and 0–2 strategy
    hyperlinks each. Two big bottom buttons link to the Patrimonial /
    Sucessório indices.

    `sorted_items`: list of (category_name, value) tuples from aggregate().
    `total`: sum of all values (used to compute slice percentages).
    `outros_components` is an optional dict mapping an "Outros (...)" label
    to the list of categories bundled inside it; used to aggregate
    strategies for the Outros callout so its hyperlinks reflect the real
    bundled categories instead of being empty.
    `jurisdiction`: 'Brasil' or 'Exterior'. Controls the title suffix
    appended to "COMPOSIÇÃO PATRIMONIAL" and triggers the empty-state
    placeholder ('Sem patrimônio no exterior declarado.') when total==0
    (only meaningful for Exterior since BR data is never empty in the
    DIRPF-driven workflow)."""
    outros_components = outros_components or {}
    # Keep legacy local names so the rest of the function (which references
    # br_sorted/total_br extensively) doesn't need a sweeping refactor.
    br_sorted = sorted_items
    total_br  = total
    from pptx.util import Inches, Emu, Pt
    from pptx.enum.shapes import MSO_SHAPE
    from pptx.enum.text import PP_ALIGN
    from pptx.dml.color import RGBColor
    from pptx.chart.data import CategoryChartData
    from pptx.enum.chart import XL_CHART_TYPE
    from pptx.oxml.ns import qn
    import math

    # Strategy theme colors for the hyperlinks beneath each callout. The
    # yellow is darkened from the brand LIME (#E4E51F) so it reads as a
    # clearly-yellow text on white without becoming illegible. Patrimonial
    # uses the dark steel blue that matches the bottom button.
    STRAT_BLUE_DARK   = RGBColor(0x1F, 0x4E, 0x79)  # deeper navy-blue
    STRAT_YELLOW_DARK = RGBColor(0x9C, 0x7A, 0x00)  # rich gold, clearly yellow

    # Wipe ONLY the old data shapes (chart + value table); keep all chrome
    # (Picture 2/10 patterns, PATRIMON.IA, COMPOSIÇÃO PATRIMONIAL title,
    # confidencial, page number) so slide 2 matches the chrome of slides 3+.
    import re as _re
    _DATA_RE = _re.compile(r'^(Rectangle|TextBox)\s*(\d+)$')
    for sh in list(sl.shapes):
        if sh.has_chart:
            sh.element.getparent().remove(sh.element)
            continue
        m = _DATA_RE.match(sh.name or '')
        # Range covers BOTH slide-2 (454-480) AND slide-3 (454-486) data
        # shape ranges, since this builder now runs on both as Brasil and
        # Exterior composition slides respectively.
        if m and 454 <= int(m.group(2)) <= 500:
            sh.element.getparent().remove(sh.element)

    # NOTE: chrome (PATRIMON.IA, HSA box top-right, navy footer band with
    # CONFIDENCIAL + page number) is already present in the template via
    # Picture 2 / Picture 10 / Text Box62 / Text Box65 / TextBox 13.
    # We DO NOT rebuild that chrome.
    #
    # BUT — the cleanup loop above wipes the LIME title bar that the outer
    # build_deck() added at line ~21831 (it lands as auto-named "Rectangle
    # 481" which falls inside the 454-500 cleanup range). So we re-add the
    # bar here, AFTER the cleanup, to keep slides 2 and 3 visually consistent
    # with slides 4/5/6 which also wear the lime title bar.
    add_title_bar(sl)
    # We DO update the title (Text 7) with the jurisdiction suffix.
    ribbon(sl, f"COMPOSIÇÃO PATRIMONIAL — {jurisdiction.upper()}")

    from pptx.enum.text import MSO_ANCHOR, MSO_AUTO_SIZE
    # Empty-state: client has no offshore patrimony to display. Render
    # a centered italic message instead of the donut/callout layout.
    if total_br == 0:
        msg = sl.shapes.add_textbox(
            Inches(1.5), Inches(3.0), prs_w - Inches(3.0), Inches(1.5)
        )
        mtf = msg.text_frame
        mtf.word_wrap = True
        mtf.vertical_anchor = MSO_ANCHOR.MIDDLE
        p = mtf.paragraphs[0]; p.alignment = PP_ALIGN.CENTER
        r = p.add_run()
        r.text = "Sem patrimônio no exterior declarado."
        r.font.name = "Gotham SSm"
        r.font.size = Pt(18)
        r.font.color.rgb = GRAY_MED
        r.font.italic = True
        return

    # ── LAYOUT: pie centred, 6 callout slots in 6 angular zones around it.
    # Each callout has a colour-square + name + value + %. Leader from
    # slice midpoint goes 2 segments: radial outward, then diagonal to the
    # callout anchor (kept entirely outside the pie). Arrowhead on the
    # callout end so direction is obvious.
    import math as _math
    from pptx.oxml.ns import qn as _qn
    from lxml import etree as _etree

    NAVY_SHADES = ['1E2D3A', '2D4356', '3D5871', '5C7791', '8DA5BF', 'B8CCDD']

    # ── PIE CHART (centred) ──
    PIE_DIA = Inches(3.4)
    PIE_X = (prs_w - PIE_DIA) // 2
    PIE_Y = Inches(2.55)
    PIE_CX = PIE_X + PIE_DIA // 2
    PIE_CY = PIE_Y + PIE_DIA // 2
    PIE_R  = PIE_DIA // 2

    chart_data = CategoryChartData()
    chart_data.categories = [name for name, _ in br_sorted]
    chart_data.add_series("", [val for _, val in br_sorted])
    chart_shape = sl.shapes.add_chart(
        XL_CHART_TYPE.PIE, PIE_X, PIE_Y, PIE_DIA, PIE_DIA, chart_data
    )
    chart = chart_shape.chart
    chart.has_title = False
    chart.has_legend = False
    plot = chart.plots[0]
    plot.has_data_labels = False
    for i, point in enumerate(plot.series[0].points):
        fill = point.format.fill
        fill.solid()
        fill.fore_color.rgb = RGBColor.from_string(NAVY_SHADES[i % len(NAVY_SHADES)])

    # ── TOTAL donut hole ──
    HOLE = Inches(1.55)
    HOLE_X = PIE_X + (PIE_DIA - HOLE) // 2
    HOLE_Y = PIE_Y + (PIE_DIA - HOLE) // 2
    hole = sl.shapes.add_shape(MSO_SHAPE.OVAL, HOLE_X, HOLE_Y, HOLE, HOLE)
    hole.fill.solid(); hole.fill.fore_color.rgb = WHITE
    hole.line.color.rgb = GRAY_LT; hole.line.width = Pt(0.5)
    tot_sh = sl.shapes.add_textbox(HOLE_X, HOLE_Y, HOLE, HOLE)
    tot_tf = tot_sh.text_frame
    tot_tf.auto_size = MSO_AUTO_SIZE.NONE; tot_tf.word_wrap = True
    tot_tf.margin_left = tot_tf.margin_right = tot_tf.margin_top = tot_tf.margin_bottom = 0
    tot_tf.vertical_anchor = MSO_ANCHOR.MIDDLE
    p = tot_tf.paragraphs[0]; p.alignment = PP_ALIGN.CENTER
    r = p.add_run(); r.text = "TOTAL"
    r.font.name = "Gotham SSm Bold"; r.font.size = Pt(10); r.font.color.rgb = GRAY_MED; r.font.bold = True
    p2 = tot_tf.add_paragraph(); p2.alignment = PP_ALIGN.CENTER
    r2 = p2.add_run(); r2.text = _brl_short(total_br)
    r2.font.name = "Gotham SSm Bold"; r2.font.size = Pt(18); r2.font.color.rgb = NAVY; r2.font.bold = True

    # ── CALLOUT SLOTS (6 side slots — 3 left, 3 right, no slots above the
    # pie). This is the layout for "titles beside each piece": every
    # callout sits beside the pie's left or right edge at one of three
    # vertical positions (top, mid, bot). Eliminates the cramped top zone
    # where multiple callouts used to compete for the same band of space.
    CALLOUT_W = Inches(3.3)
    CALLOUT_H = Inches(1.05)
    LEFT_X    = Inches(0.30)
    RIGHT_X   = Inches(9.70)

    # Pie slice midangles (0 = 12 o'clock, CW). Slices are drawn in the
    # order of br_sorted (largest first), so index i corresponds to the
    # i-th slice on the pie going CW from 12 o'clock.
    _total_vals = sum(v for _, v in br_sorted[:6]) or 1
    slice_midangles = []
    slice_arc_starts = []
    slice_arc_ends   = []
    _cum = 0
    for _, _v in br_sorted[:6]:
        s = _cum / _total_vals * 2 * _math.pi
        e = (_cum + _v) / _total_vals * 2 * _math.pi
        slice_midangles.append((s + e) / 2)
        slice_arc_starts.append(s)
        slice_arc_ends.append(e)
        _cum += _v

    # ── SIDE ASSIGNMENT (which slices go to left column vs right column) ──
    n_slices = len(br_sorted[:6])
    sides_arr = ['left' if _math.pi < m <= 2*_math.pi else 'right'
                  for m in slice_midangles[:n_slices]]
    left_idxs  = [i for i, s in enumerate(sides_arr) if s == 'left']
    right_idxs = [i for i, s in enumerate(sides_arr) if s == 'right']

    # Rebalance: at most 3 slices per side. Move slices closest to the
    # 12-o'clock wrap across, since they're geometrically near both sides.
    while len(left_idxs) > 3:
        mv = min(left_idxs, key=lambda i: 2*_math.pi - slice_midangles[i])
        sides_arr[mv] = 'right'; left_idxs.remove(mv); right_idxs.append(mv)
    while len(right_idxs) > 3:
        mv = min(right_idxs, key=lambda i: slice_midangles[i])
        sides_arr[mv] = 'left'; right_idxs.remove(mv); left_idxs.append(mv)

    # ── SPREAD ARROW ANCHOR ANGLES ──
    # When two slices are adjacent on the pie AND go to callouts on the
    # same side (e.g. Bens Móveis 345° + Outros 355° — only 10° apart),
    # their arrow start points overlap visually, making it look like both
    # arrows point to the same segment. Push each anchor along its own
    # slice's arc to enforce a minimum angular separation.
    anchor_angles = list(slice_midangles)
    spatial_order = sorted(range(n_slices), key=lambda i: slice_midangles[i])
    MIN_ANGLE_SEP = _math.radians(22)
    ARC_MARGIN    = _math.radians(2)  # keep anchor at least this far inside slice
    for _ in range(5):
        for k in range(len(spatial_order)):
            i = spatial_order[k]
            j = spatial_order[(k + 1) % len(spatial_order)]
            if sides_arr[i] != sides_arr[j]:
                continue
            diff = anchor_angles[j] - anchor_angles[i]
            if diff < 0:
                diff += 2 * _math.pi
            if diff < MIN_ANGLE_SEP:
                push = (MIN_ANGLE_SEP - diff) / 2
                # Push slice i CCW (toward its arc start)
                max_push_i = max(0, anchor_angles[i] - slice_arc_starts[i] - ARC_MARGIN)
                anchor_angles[i] -= min(push, max_push_i)
                # Push slice j CW (toward its arc end)
                max_push_j = max(0, slice_arc_ends[j] - anchor_angles[j] - ARC_MARGIN)
                anchor_angles[j] += min(push, max_push_j)

    # ── DYNAMIC SLOT PLACEMENT ──
    # Instead of fixed Y positions (1.65 / 3.65 / 5.20), each callout's Y is
    # computed from its slice's natural Y on the pie edge. With callouts at
    # their slice's own Y level, the leader is nearly horizontal and never
    # has to cross another leader to reach a different vertical band.
    # Greedy top-down placement enforces a minimum gap between callouts;
    # the last callout is clamped so it never enters the button zone.
    MIN_CALLOUT_TOP    = Inches(1.10)
    MAX_CALLOUT_BOTTOM = Inches(6.05)  # buttons start at Y=6.20, leave 0.15in gap
    MIN_CALLOUT_GAP    = Inches(0.15)

    def _place_side(idxs, x_pos, side_name):
        """Return {slice_idx → (cx, cy, side, anchor_x, anchor_y)}. Callouts
        are ordered by spatial CW position on the pie (not by Y projection),
        so the slice geographically furthest along the slide's vertical
        edge gets the topmost slot."""
        if not idxs:
            return {}
        ideal = []
        for i in idxs:
            ang = anchor_angles[i]
            y_pie_edge = PIE_CY - int(_math.cos(ang) * PIE_R)
            ideal.append((i, y_pie_edge - CALLOUT_H // 2))

        # Sort by angular CW spatial order on the pie:
        # - LEFT side: midangle DESC (closer to 360° wrap = upper-left → top)
        # - RIGHT side: wrapped midangle ASC (wrapped slices from 270-360°
        #   range take precedence so their longer leaders can route along
        #   the top of the pie at the highest slot)
        if side_name == 'left':
            ideal.sort(key=lambda x: -anchor_angles[x[0]])
        else:
            def _right_key(item):
                a = anchor_angles[item[0]]
                return a - 2*_math.pi if a > _math.pi else a
            ideal.sort(key=_right_key)

        # Forward pass: push down to satisfy MIN_TOP and minimum gap
        placed = []
        cursor = MIN_CALLOUT_TOP
        for i, y in ideal:
            y = max(y, cursor)
            placed.append([i, y])
            cursor = y + CALLOUT_H + MIN_CALLOUT_GAP

        # Backward pass: if anything overshoots MAX_BOTTOM, cascade upward
        max_top = MAX_CALLOUT_BOTTOM - CALLOUT_H
        for k in range(len(placed)-1, -1, -1):
            if placed[k][1] > max_top:
                placed[k][1] = max_top
                max_top = max_top - CALLOUT_H - MIN_CALLOUT_GAP
            else:
                break

        result = {}
        for i, y in placed:
            ax = x_pos if side_name == 'right' else x_pos + CALLOUT_W
            ay = y + CALLOUT_H // 2
            result[i] = (x_pos, y, side_name, ax, ay)
        return result

    slot_assignments = {}
    slot_assignments.update(_place_side(left_idxs,  LEFT_X,  'left'))
    slot_assignments.update(_place_side(right_idxs, RIGHT_X, 'right'))

    def _add_arrow_tail(conn):
        ln = conn.line._get_or_add_ln()
        for e in ln.findall(_qn('a:tailEnd')):
            ln.remove(e)
        t = _etree.SubElement(ln, _qn('a:tailEnd'))
        t.set('type','triangle'); t.set('w','med'); t.set('len','med')

    # Helper: textbox with fixed frame (no autofit shenanigans)
    def _fixed_tf(x, y, w, h):
        tf = sl.shapes.add_textbox(x, y, w, h).text_frame
        tf.auto_size = MSO_AUTO_SIZE.NONE; tf.word_wrap = True
        tf.margin_left = tf.margin_right = tf.margin_top = tf.margin_bottom = 0
        return tf

    callout_strategy_shapes = []   # (textbox_shape, strategy_name)

    # Per-slice bulge intensity. The top-slot slice on each side gets a
    # high bulge when its leader has to traverse across the pie. Other
    # wrapped slices (rebalanced from their natural geographic side to
    # the opposite callout column) get a medium bulge so their curves
    # arc visibly upward off the slice instead of running nearly straight
    # toward the callout.
    bulge_factor = [0.10] * n_slices
    for side_name in ('left', 'right'):
        if side_name == 'left':
            _key = lambda i: -anchor_angles[i]
        else:
            def _key(i, _a=anchor_angles, _pi=_math.pi):
                a = _a[i]
                return a - 2*_pi if a > _pi else a
        side_sorted = sorted(
            [i for i in range(n_slices) if sides_arr[i] == side_name],
            key=_key,
        )
        for rank, i in enumerate(side_sorted):
            ang = anchor_angles[i]
            natural_side = 'left' if _math.pi < ang <= 2*_math.pi else 'right'
            is_wrapped = (natural_side != side_name)

            if rank == 0 and len(side_sorted) >= 2:
                s1x = PIE_CX + _math.sin(ang) * PIE_R
                s1y = PIE_CY - _math.cos(ang) * PIE_R
                _, _, _, ax_chk, ay_chk = slot_assignments[i]
                length = ((ax_chk - s1x)**2 + (ay_chk - s1y)**2) ** 0.5
                if length > Inches(2.0):
                    bulge_factor[i] = 0.32  # top slot, long arrow: big arc
            elif is_wrapped:
                bulge_factor[i] = 0.22  # wrapped non-top: medium arc

    def _draw_curved_leader(x1, y1, x2, y2, color_hex, factor):
        """Draw a curved arrow from (x1,y1) to (x2,y2) using a single cubic
        Bezier that bulges outward from the pie center. `factor` controls
        the bulge magnitude as a fraction of line length."""
        # Outward bulge: push control point AWAY from (PIE_CX, PIE_CY)
        mx = (x1 + x2) / 2.0
        my = (y1 + y2) / 2.0
        dx_pie = mx - PIE_CX
        dy_pie = my - PIE_CY
        dist_pie = (dx_pie*dx_pie + dy_pie*dy_pie) ** 0.5
        line_len = ((x2-x1)**2 + (y2-y1)**2) ** 0.5
        bulge = min(line_len * factor, 800_000)  # cap at ~0.87 inch
        if dist_pie > 0:
            ux = dx_pie / dist_pie
            uy = dy_pie / dist_pie
            cpx = mx + ux * bulge
            cpy = my + uy * bulge
        else:
            cpx, cpy = mx, my

        # Bounding box including the control point (to size the shape)
        min_x = min(x1, x2, cpx); max_x = max(x1, x2, cpx)
        min_y = min(y1, y2, cpy); max_y = max(y1, y2, cpy)
        box_w = max(int(max_x - min_x), 1)
        box_h = max(int(max_y - min_y), 1)
        p_x1 = int(x1 - min_x); p_y1 = int(y1 - min_y)
        p_x2 = int(x2 - min_x); p_y2 = int(y2 - min_y)
        p_cpx = int(cpx - min_x); p_cpy = int(cpy - min_y)

        width_emu = int(1.5 * 12700)  # 1.5 pt → EMU
        # Pick a high shape id that won't collide
        existing = [int(s.shape_id) for s in sl.shapes if str(s.shape_id).isdigit()]
        next_id = max(existing, default=1000) + 1

        sp_xml = f'''<p:sp xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">
  <p:nvSpPr>
    <p:cNvPr id="{next_id}" name="CurvedLeader"/>
    <p:cNvSpPr/>
    <p:nvPr/>
  </p:nvSpPr>
  <p:spPr>
    <a:xfrm>
      <a:off x="{int(min_x)}" y="{int(min_y)}"/>
      <a:ext cx="{box_w}" cy="{box_h}"/>
    </a:xfrm>
    <a:custGeom>
      <a:avLst/>
      <a:gdLst/>
      <a:ahLst/>
      <a:cxnLst/>
      <a:rect l="0" t="0" r="0" b="0"/>
      <a:pathLst>
        <a:path w="{box_w}" h="{box_h}">
          <a:moveTo>
            <a:pt x="{p_x1}" y="{p_y1}"/>
          </a:moveTo>
          <a:cubicBezTo>
            <a:pt x="{p_cpx}" y="{p_cpy}"/>
            <a:pt x="{p_cpx}" y="{p_cpy}"/>
            <a:pt x="{p_x2}" y="{p_y2}"/>
          </a:cubicBezTo>
        </a:path>
      </a:pathLst>
    </a:custGeom>
    <a:noFill/>
    <a:ln w="{width_emu}" cap="rnd">
      <a:solidFill>
        <a:srgbClr val="{color_hex}"/>
      </a:solidFill>
      <a:headEnd type="triangle" w="med" len="med"/>
    </a:ln>
  </p:spPr>
  <p:txBody>
    <a:bodyPr/>
    <a:lstStyle/>
    <a:p><a:endParaRPr lang="pt-BR"/></a:p>
  </p:txBody>
</p:sp>'''
        elem = _etree.fromstring(sp_xml)
        sl.shapes._spTree.append(elem)

    for i, (name, val) in enumerate(br_sorted[:6]):
        cx, cy, side, ax, ay = slot_assignments[i]
        pct = (val / total_br * 100) if total_br else 0
        slice_color = NAVY_SHADES[i % len(NAVY_SHADES)]
        ang = anchor_angles[i]   # spread anchor angle (within slice arc)

        # UNIFORM tip penetration: every arrow tip lands at the SAME depth
        # just inside the donut ring (93% of PIE_R from center). This gives
        # every callout the same visual "touching the slice" feel — earlier
        # iterations had only the smallest slice penetrate, which made the
        # other arrows look like they barely reached the pie.
        tip_radius = PIE_R * 0.93
        s1x = PIE_CX + int(_math.sin(ang) * tip_radius)
        s1y = PIE_CY - int(_math.cos(ang) * tip_radius)

        _draw_curved_leader(s1x, s1y, ax, ay, slice_color, bulge_factor[i])

        # Callout text: bullet + name on line 1, value + % on line 2,
        # up to 2 strategy hyperlinks on lines 3-4.
        align = (PP_ALIGN.CENTER if side == "top"
                 else PP_ALIGN.LEFT if side == "right"
                 else PP_ALIGN.RIGHT)
        head = _fixed_tf(cx, cy, CALLOUT_W, Inches(0.24))
        p = head.paragraphs[0]; p.alignment = align
        rb = p.add_run(); rb.text = "■ "
        rb.font.size = Pt(10); rb.font.color.rgb = RGBColor.from_string(slice_color); rb.font.bold = True
        # For long "Outros (...)" labels with 4+ bundled categories, the
        # parenthetical doesn't fit on one line at 8pt. Split: show
        # "OUTROS" on the title line and the bundled list at 7pt on the
        # next line so the value (line 2 of the callout) doesn't collide.
        display_name = name
        sub_line = None
        if name.startswith("Outros (") and name.endswith(")"):
            inner = name[len("Outros ("):-1]
            parts = inner.split(" + ")
            if len(parts) >= 4:
                display_name = "Outros"
                sub_line = inner
        rn = p.add_run(); rn.text = display_name.upper()
        rn.font.name = "Gotham SSm Bold"; rn.font.size = Pt(8); rn.font.color.rgb = GRAY_MED; rn.font.bold = True
        if sub_line:
            psub = head.add_paragraph(); psub.alignment = align
            rs = psub.add_run(); rs.text = f"({sub_line})"
            rs.font.name = "Gotham SSm"; rs.font.size = Pt(6); rs.font.color.rgb = GRAY_MED; rs.font.italic = True
        val_y_offset = Inches(0.34) if sub_line else Inches(0.22)
        valbox = _fixed_tf(cx, cy + val_y_offset, CALLOUT_W, Inches(0.32))
        p = valbox.paragraphs[0]; p.alignment = align
        rv = p.add_run(); rv.text = f"{_brl_short(val)}  "
        rv.font.name = "Gotham SSm Bold"; rv.font.size = Pt(13); rv.font.color.rgb = NAVY; rv.font.bold = True
        rp = p.add_run(); rp.text = f"({pct:.1f}%)"
        rp.font.name = "Gotham SSm Bold"; rp.font.size = Pt(9); rp.font.color.rgb = GRAY_MED

        # Strategy hyperlinks — up to 2, beneath the value line. Direction
        # arrow (›/‹) matches the callout's side so the eye knows which
        # text is clickable and which way it "points" into the index slide.
        # IMPORTANT: the hyperlink is attached to the textbox SHAPE (cNvPr),
        # NOT to the text run. If it were on the run, PowerPoint would
        # substitute the run's text colour with the theme's hyperlink
        # colour, wiping out the gold/blue distinction we set below.
        # Resolve the strategies to show under this callout. For a regular
        # category that's just a CATEGORY_STRATEGIES lookup. For the
        # synthetic "Outros (...)" bucket, no direct entry exists — so we
        # pool the strategies of the underlying bundled categories
        # (deduped, keeping first occurrence; capped at 2 to fit the slot).
        if name in outros_components:
            pooled = []
            seen = set()
            for comp_name in outros_components[name]:
                for s_tuple in CATEGORY_STRATEGIES.get(comp_name, []):
                    if s_tuple[0] not in seen:
                        seen.add(s_tuple[0])
                        pooled.append(s_tuple)
            strategies = pooled[:2]
        else:
            strategies = CATEGORY_STRATEGIES.get(name, [])[:2]
        for j, (sname, theme) in enumerate(strategies):
            s_y = cy + Inches(0.56) + j * Inches(0.20)
            stx_shape = sl.shapes.add_textbox(cx, s_y, CALLOUT_W, Inches(0.20))
            stf = stx_shape.text_frame
            stf.auto_size = MSO_AUTO_SIZE.NONE; stf.word_wrap = True
            stf.margin_left = stf.margin_right = stf.margin_top = stf.margin_bottom = 0
            p = stf.paragraphs[0]; p.alignment = align
            color = STRAT_BLUE_DARK if theme == "patrimonial" else STRAT_YELLOW_DARK
            if side == "right":
                txt = f"› {short_strategy(sname)}"
            elif side == "left":
                txt = f"{short_strategy(sname)} ‹"
            else:  # top
                txt = f"› {short_strategy(sname)}"
            rs = p.add_run(); rs.text = txt
            rs.font.name = "Gotham SSm Bold"; rs.font.size = Pt(8); rs.font.color.rgb = color; rs.font.bold = True
            rs.font.underline = True
            callout_strategy_shapes.append((stx_shape, sname))

    # ── 2 big bottom buttons ──
    BTN_W = Inches(3.5); BTN_H = Inches(0.50)
    BTN_GAP = Inches(0.30)
    BTN_Y = prs_h - Inches(1.30)
    BTN_X1 = (prs_w - BTN_W*2 - BTN_GAP) // 2
    BTN_X2 = BTN_X1 + BTN_W + BTN_GAP

    def _make_button(x, y, label, fill_color, text_color):
        btn = sl.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, BTN_W, BTN_H)
        btn.fill.solid(); btn.fill.fore_color.rgb = fill_color
        btn.line.fill.background()
        tf = btn.text_frame
        tf.margin_left = tf.margin_top = tf.margin_bottom = 0
        p = tf.paragraphs[0]; p.alignment = PP_ALIGN.CENTER
        r = p.add_run(); r.text = label
        r.font.name = "Gotham SSm Bold"; r.font.size = Pt(11); r.font.color.rgb = text_color; r.font.bold = True
        return r

    btn_p_run = _make_button(BTN_X1, BTN_Y, "📋  Ver Estratégias Patrimoniais", STRAT_BLUE_DARK, WHITE)
    btn_s_run = _make_button(BTN_X2, BTN_Y, "📋  Ver Estratégias Sucessórias", STRAT_YELLOW_DARK, WHITE)

    # NOTE: footer (navy band + CONFIDENCIAL + page number) intentionally
    # NOT rebuilt — template's Picture 10 / Text Box65 / TextBox 13 are
    # preserved by the selective-wipe at the top of this function, so
    # slide 2's footer now matches slides 3+.

    # ── Wire hyperlinks ──
    # Strategy textboxes → individual strategy slides. We attach hlinkClick
    # to the SHAPE (cNvPr) rather than to the text run. This is the only
    # reliable way to keep our custom gold/blue text colour: PowerPoint
    # substitutes the theme's hyperlink colour for any run with hlinkClick
    # but leaves the text alone when the hyperlink lives on the parent
    # shape. The shape stays fully clickable (the cursor still turns into
    # a hand when hovering the text), so the user experience is identical.
    for shape, strategy_name in callout_strategy_shapes:
        target = strategy_slides.get(strategy_name)
        if target is not None:
            _shape_internal_hyperlink(sl, shape, target)
    # Bottom buttons → indices. These keep run-level hyperlinks since the
    # button shapes have a solid fill behind the text and the substituted
    # hyperlink colour is barely visible there.
    _internal_hyperlink(sl, btn_p_run, indice_p)
    _internal_hyperlink(sl, btn_s_run, indice_s)


def _brl_short(v):
    """Compact BRL: R$ 5.0M / R$ 612K / R$ 0,00"""
    if v >= 1_000_000_000: return f"R$ {v/1e9:.1f}B"
    if v >= 1_000_000:     return f"R$ {v/1e6:.1f}M"
    if v >= 1_000:         return f"R$ {v/1e3:.0f}K"
    return f"R$ {v:,.0f}".replace(",", ".")


def _shape_internal_hyperlink(slide, shape, target_slide):
    """Attach a hyperlink to a SHAPE rather than to a text run. This avoids
    PowerPoint's theme-hyperlink-colour substitution, which only acts on
    runs that carry <a:hlinkClick>. The hyperlink lives on the shape's
    <p:cNvPr> element, so the entire shape (including its text) is
    clickable but the text retains its explicitly-set colour."""
    from pptx.oxml.ns import qn
    from lxml import etree as _ET
    target_part = target_slide.part
    rId = slide.part.relate_to(
        target_part,
        'http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide'
    )
    # Walk down into the shape's nvSpPr to find <p:cNvPr>. Different shape
    # types (autoshape, textbox, picture) all have one cNvPr near the top.
    cNvPr = shape._element.find('.//' + qn('p:cNvPr'))
    if cNvPr is None:
        return
    # Remove any prior hlinkClick on this shape, then add the new one.
    for h in cNvPr.findall(qn('a:hlinkClick')):
        cNvPr.remove(h)
    hlink = _ET.SubElement(cNvPr, qn('a:hlinkClick'))
    hlink.set(qn('r:id'), rId)
    hlink.set('action', 'ppaction://hlinksldjump')


def _internal_hyperlink(slide, run, target_slide):
    """Make a run hyperlink to an internal slide via <a:hlinkClick>."""
    from pptx.oxml.ns import qn
    target_part = target_slide.part
    rId = slide.part.relate_to(
        target_part,
        'http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide'
    )
    run_elem = run._r
    rPr = run_elem.find(qn('a:rPr'))
    if rPr is None:
        rPr = run_elem.makeelement(qn('a:rPr'), {})
        run_elem.insert(0, rPr)
    for h in rPr.findall(qn('a:hlinkClick')):
        rPr.remove(h)
    hlink = rPr.makeelement(qn('a:hlinkClick'), {
        qn('r:id'): rId,
        'action': 'ppaction://hlinksldjump',
    })
    rPr.append(hlink)


def build_deck(data, output_path):
    agg = aggregate(data)
    CLIENT   = agg['client']
    br       = agg['br_sorted']        # [(name, value), ...] sorted desc
    off      = agg['off_sorted']
    TOTAL_BR = agg['total_br']
    TOTAL_OFF= agg['total_off']
    BR_OUTROS_COMPONENTS = agg.get('br_outros_components', {})

    # ── Stage 1: copy + strip orphans ────────────────────────────────────────
    shutil.copy(REF_TEMPLATE, output_path)
    strip_orphans(output_path)

    prs = Presentation(output_path)

    # ── Fix slide number style on all slides (TextBox 13) ────────────────────
    # Template has it bold + inherited color. We want: Gotham SSm Black, NOT
    # bold, grey (#8E959B), 9pt — matching the reference screenshot.
    for sl in prs.slides:
        for sh in sl.shapes:
            if sh.name == 'TextBox 13' and hasattr(sh, 'text_frame'):
                for para in sh.text_frame.paragraphs:
                    for run in para.runs:
                        run.font.name  = 'Gotham SSm Black'
                        run.font.bold  = False
                        run.font.size  = Pt(11.7)
                        run.font.color.rgb = GRAY_MED
                break

    def rep(slide, old, new):
        for sh in slide.shapes:
            if hasattr(sh,'text_frame') and old in sh.text:
                for para in sh.text_frame.paragraphs:
                    for run in para.runs:
                        if old in run.text:
                            run.text = run.text.replace(old, new)
                            return True
        return False

    # ── Slide 1: client name ─────────────────────────────────────────────────
    rep(prs.slides[0], 'CAROL G', CLIENT)

    # ── Add HSA-style yellow title bar to slides 2-4 ─────────────────────────
    # (Slides 5-6 get clear()ed later and need the bar added after that.)
    for slide_idx in range(1, 4):
        add_title_bar(prs.slides[slide_idx])

    # ── Build 6 slots from Brasil groups (pad with blanks) ───────────────────
    # Carol G's template values, by row order:
    CG_VALS = ['R$ 23.7M','R$ 10.4M','R$ 11.7M','R$ 2.2M','R$ 0.7M','R$ 1.5M']
    CG_PCTS = ['47.1%','20.8%','23.3%','4.4%','1.4%','3.0%']
    CG_LBL_UPPER = ['PART. SOCIETÁRIAS','APLICAÇÕES E INVEST.','IMÓVEIS',
                    'OBRAS DE ARTE','CONTAS BANCÁRIAS','CRÉDITOS E DIREITOS']
    CG_LBL_TITLE = ['Part. Societárias','Aplicações e Invest.','Imóveis',
                    'Obras de Arte','Contas Bancárias','Créditos e Direitos']

    slots = []
    for i in range(6):
        if i < len(br):
            name, val = br[i]
            pct = (val/TOTAL_BR*100) if TOTAL_BR else 0
            slots.append({'name':name, 'val':val,
                          'val_str':brl(val), 'pct_str':f"{pct:.1f}%"})
        else:
            slots.append({'name':'—', 'val':0, 'val_str':'—', 'pct_str':'—'})

    BR_TOTAL_STR = brl(TOTAL_BR)

    # ── Slide 2: composition ─────────────────────────────────────────────────
    # Replace template labels with real category names. We do this in ONE atomic
    # pass per text frame using direct XML find/replace, so a substitution in
    # slot 0 can't affect the label of slot 2 (the old approach of replacing
    # one at a time could create substring collisions: e.g. setting slot 0 to
    # "BENS IMÓVEIS" then trying to find "IMÓVEIS" for slot 2 would match the
    # newly-written slot-0 text).
    s2 = prs.slides[1]

    # Build name+value+pct triples. We need to map template-text → real text
    # for each slot. The template carries the exact strings in CG_LBL_UPPER /
    # CG_VALS / CG_PCTS, one per slot.
    label_map = {}
    val_map   = {}
    pct_map   = {}
    for i in range(6):
        label_map[CG_LBL_UPPER[i]] = slots[i]['name'].upper()
        val_map[CG_VALS[i]]        = slots[i]['val_str']
        pct_map[CG_PCTS[i]]        = slots[i]['pct_str']

    def _replace_runs(textframe, mapping):
        """For each run inside textframe, if its exact text matches a key in
        `mapping`, replace it with the value. Atomic per-run — no substring."""
        for para in textframe.paragraphs:
            for run in para.runs:
                t = run.text
                if t in mapping:
                    run.text = mapping[t]

    for sh in s2.shapes:
        if not hasattr(sh, 'text_frame'):
            continue
        _replace_runs(sh.text_frame, label_map)
        _replace_runs(sh.text_frame, val_map)
        _replace_runs(sh.text_frame, pct_map)
    rep(s2, 'R$ 50.3M', BR_TOTAL_STR)

    # FIX #1: the template highlights row 2 with lime (Rectangle 458 = D4E142).
    # That highlight is arbitrary per-client noise — normalise row 2 to the
    # same grey (E4E9EB) the other rows use, NOT transparent.
    ROW_GREY = RGBColor(0xE4, 0xE9, 0xEB)
    for sh in s2.shapes:
        if sh.name == 'Rectangle 458':
            sh.fill.solid()
            sh.fill.fore_color.rgb = ROW_GREY
            break

    # FIX #2: reposition TOTAL GERAL — left label + right value, vertically centred
    NAVY_BAR_Y = 4974336
    NAVY_BAR_H = 566928
    BAR_MID    = NAVY_BAR_Y + NAVY_BAR_H // 2
    for sh in s2.shapes:
        if sh.name == 'TextBox 479':   # "TOTAL GERAL"
            sh.left   = Emu(6420000)
            sh.width  = Emu(2400000)
            sh.height = Emu(280000)
            sh.top    = Emu(BAR_MID - 140000)
            tf = sh.text_frame
            try: tf.vertical_anchor = MSO_ANCHOR.MIDDLE
            except: pass
            for p in tf.paragraphs:
                p.alignment = PP_ALIGN.LEFT
                for r in p.runs:
                    r.font.size = Pt(11)
                    r.font.bold = True
                    r.font.name = 'Gotham SSm Bold'
                    r.font.color.rgb = LIME
        elif sh.name == 'TextBox 480':  # "R$ X.XM"
            sh.left   = Emu(8800000)
            sh.width  = Emu(2950000)
            sh.height = Emu(420000)
            sh.top    = Emu(BAR_MID - 210000)
            tf = sh.text_frame
            try: tf.vertical_anchor = MSO_ANCHOR.MIDDLE
            except: pass
            for p in tf.paragraphs:
                p.alignment = PP_ALIGN.RIGHT
                for r in p.runs:
                    r.font.size = Pt(22)
                    r.font.bold = True
                    r.font.name = 'Gotham SSm Bold'
                    r.font.color.rgb = WHITE

    # FIX #3: every row textbox on slide 2 (PART. SOCIETÁRIAS, R$ values,
    # percentages) inherits Calibri — no explicit <a:latin>. Force Gotham
    # on all of them, preserving each one's original size.
    for sh in s2.shapes:
        if not sh.name.startswith('TextBox'): continue
        if sh.name in ('TextBox 479', 'TextBox 480'): continue  # done above
        if not hasattr(sh, 'text_frame'): continue
        for para in sh.text_frame.paragraphs:
            for run in para.runs:
                run.font.name = 'Gotham SSm Bold'
                run.font.bold = True

    # ── COMPACT THE 6-ROW LIST ──────────────────────────────────────────────
    # The Carol G template spaces the 6 list rows generously (each 475_488
    # tall, 64_008 gaps). That leaves the numbers looking too spread out.
    # Shrink each row's height and tighten the gaps, then re-stack every
    # row's rectangle + its 3 textboxes, and pull the TOTAL bar up to follow.
    ROW_RECTS = ['Rectangle 454','Rectangle 458','Rectangle 462',
                 'Rectangle 466','Rectangle 470','Rectangle 474']
    TOTAL_RECT = 'Rectangle 478'
    # the 3 textboxes that belong to each row, in template order
    ROW_TBOXES = [
        ('TextBox 455','TextBox 457','TextBox 456'),  # row 1: label, %, value
        ('TextBox 459','TextBox 461','TextBox 460'),  # row 2
        ('TextBox 463','TextBox 465','TextBox 464'),  # row 3
        ('TextBox 467','TextBox 469','TextBox 468'),  # row 4
        ('TextBox 471','TextBox 473','TextBox 472'),  # row 5
        ('TextBox 475','TextBox 477','TextBox 476'),  # row 6
    ]
    by_name = {sh.name: sh for sh in s2.shapes}

    # Hide empty slots (val == 0) — make the rect background transparent and
    # set all text to white so nothing shows. Keeps geometry intact.
    for i, rect_name in enumerate(ROW_RECTS):
        if slots[i]['val'] == 0:
            rect = by_name.get(rect_name)
            if rect is not None:
                rect.fill.background()
                rect.line.fill.background()
            for tb_name in ROW_TBOXES[i]:
                tb = by_name.get(tb_name)
                if tb is not None:
                    for para in tb.text_frame.paragraphs:
                        for run in para.runs:
                            run.font.color.rgb = WHITE

    # FIX #5: rebalance slide 2 layout — pie was left-skewed and value table
    # was off-centre on the right half. Shift both toward slide centre.
    # Constraint: TextBox 480 (TOTAL value) right edge must stay within
    # slide width (12_192_000). After FIX #2 it is at L=8_800_000 W=2_950_000
    # → right=11_750_000. Max safe shift ≈ 400_000.
    PIE_SHIFT_X  = 200_000   # smaller shift — pie stays more on the left
    RECT_SHIFT_X = 350_000   # value table moves right modestly (keeps 480 on slide)

    # Move pie chart
    for sh in s2.shapes:
        if sh.has_chart:
            sh.left = Emu(sh.left + PIE_SHIFT_X)
            break

    # Shift all row rects + their 3 textboxes + TOTAL bar/labels
    SHIFT_SHAPES = (
        ['Rectangle 454','Rectangle 458','Rectangle 462',
         'Rectangle 466','Rectangle 470','Rectangle 474','Rectangle 478']
        + [f'TextBox {n}' for n in (455,456,457,459,460,461,463,464,465,
                                     467,468,469,471,472,473,475,476,477,
                                     479,480)]
    )
    for nm in SHIFT_SHAPES:
        sh = by_name.get(nm)
        if sh is not None:
            sh.left = Emu(sh.left + RECT_SHIFT_X)

    # FIX #10: TextBox 480 (TOTAL value) was extending past the navy TOTAL bar's
    # right edge → text rendered partly outside the bar and got clipped at the
    # slide edge. Pin both 479 (label) and 480 (value) inside the bar.
    bar = by_name.get('Rectangle 478')
    if bar is not None:
        bar_left  = bar.left
        bar_right = bar.left + bar.width
        tb479 = by_name.get('TextBox 479')   # "TOTAL GERAL"
        tb480 = by_name.get('TextBox 480')   # value "R$ X.XM"
        if tb479 is not None:
            tb479.left  = Emu(bar_left + 120_000)
            tb479.width = Emu(1_800_000)
        if tb480 is not None:
            tb480.width = Emu(1_900_000)
            tb480.left  = Emu(bar_right - 1_900_000 - 80_000)

    # original first-row top stays the same; everything below moves up
    FIRST_TOP = 1_737_360          # template y of Rectangle 454
    NEW_ROW_H = 510_000            # row height — thin but not too compact
    NEW_GAP   = 60_000             # gap between rows
    STRIDE    = NEW_ROW_H + NEW_GAP

    for i, rect_name in enumerate(ROW_RECTS):
        rect = by_name.get(rect_name)
        if rect is None: continue
        new_top = FIRST_TOP + i * STRIDE
        rect.top    = Emu(new_top)
        rect.height = Emu(NEW_ROW_H)
        # 3 textboxes per row: label sits near the top, value just below it,
        # percentage vertically centred on the right.
        lbl_name, pct_name, val_name = ROW_TBOXES[i]
        lbl = by_name.get(lbl_name)
        pct = by_name.get(pct_name)
        val = by_name.get(val_name)
        if lbl is not None:
            lbl.height = Emu(160_000)
            lbl.top = Emu(new_top + 50_000)
        if val is not None:
            val.height = Emu(260_000)
            val.top = Emu(new_top + 220_000)
            # FIX #9: bump value font size — was inheriting template size
            for para in val.text_frame.paragraphs:
                for run in para.runs:
                    run.font.size = Pt(14)
        if pct is not None:
            pct.top = Emu(new_top + (NEW_ROW_H - pct.height)//2)
            # bigger percentage too
            for para in pct.text_frame.paragraphs:
                for run in para.runs:
                    run.font.size = Pt(12)

    # TOTAL bar: thinner now (was 876_000 EMU, looked too thick). We compensate
    # by adding a bigger gap above it so the table's overall bottom (and the
    # pie's bottom) stays at the same y as before — keeping pie ↔ table aligned.
    total_rect = by_name.get(TOTAL_RECT)
    if total_rect is not None:
        NEW_TOTAL_H   = 500_000          # was 876_000 — slimmer
        EXTRA_GAP     = 446_000          # absorb the height we removed (876-500+70=446)
        new_total_top = FIRST_TOP + 5*STRIDE + NEW_ROW_H + EXTRA_GAP
        total_rect.top = Emu(new_total_top)
        total_rect.height = Emu(NEW_TOTAL_H)
        total_h = NEW_TOTAL_H
        # centre the TOTAL GERAL label + value vertically inside the slimmer bar
        bar_mid = new_total_top + total_h//2
        tb479 = by_name.get('TextBox 479')   # "TOTAL GERAL"
        tb480 = by_name.get('TextBox 480')   # value
        if tb479 is not None:
            tb479.top = Emu(bar_mid - 140_000)
        if tb480 is not None:
            tb480.top = Emu(bar_mid - 210_000)

        # FIX #8: align the pie chart vertically with the value table —
        # same top, same bottom. Bottom is the bottom of the TOTAL bar.
        TABLE_TOP    = FIRST_TOP
        TABLE_BOTTOM = new_total_top + total_h
        for sh in s2.shapes:
            if sh.has_chart:
                sh.top    = Emu(TABLE_TOP)
                sh.height = Emu(TABLE_BOTTOM - TABLE_TOP)
                break

    # ── Slide 3: detalhamento ────────────────────────────────────────────────
    s3 = prs.slides[2]
    kill_ghost_text7(s3)   # remove leftover "TOTAL ATIVOS" Calibri ghost label
    for cg_idx in sorted(range(6), key=lambda k: -len(CG_LBL_TITLE[k])):
        rep(s3, CG_LBL_TITLE[cg_idx], slots[cg_idx]['name'])
    for cg_idx in range(6):
        rep(s3, CG_VALS[cg_idx], slots[cg_idx]['val_str'])
        rep(s3, CG_PCTS[cg_idx], slots[cg_idx]['pct_str'])
    rep(s3, 'R$ 50.3M', BR_TOTAL_STR)

    # Hide KPI cards on slide 3 for empty slots (val == 0) —
    # The 6 KPI rectangles in the template are named 'Rectangle 484..489'
    # (or similar). We find them by matching the category label text we just
    # wrote and make them invisible, same technique as slide 2.
    # Instead of guessing rect names, find ALL textboxes on s3 that contain
    # the placeholder "—" (which we wrote for empty slots) and hide the
    # rectangle that overlaps them.
    s3_by_name = {sh.name: sh for sh in s3.shapes}
    for cg_idx in range(6):
        if slots[cg_idx]['val'] == 0:
            # Make label, value and pct text white (invisible on white background)
            for placeholder in (CG_LBL_TITLE[cg_idx], CG_VALS[cg_idx], CG_PCTS[cg_idx]):
                for sh in s3.shapes:
                    if hasattr(sh, 'text') and sh.text.strip() in ('—', placeholder, slots[cg_idx]['val_str']):
                        try:
                            for para in sh.text_frame.paragraphs:
                                for run in para.runs:
                                    run.font.color.rgb = WHITE
                        except Exception:
                            pass

    # ── Slide 4: participações ───────────────────────────────────────────────
    s4 = prs.slides[3]
    kill_ghost_text7(s4)   # remove leftover small "BRASIL" Calibri ghost label
    # Header values: Brasil = biggest "Participações"-type group OR total Part.Soc
    # Find a group whose name contains 'ociet' (Participações Societárias)
    br_soc = next((v for n,v in br if 'ociet' in n.lower()), TOTAL_BR)
    rep(s4, 'R$ 23.7M', brl(br_soc))
    rep(s4, 'US$ 6.2M', usd(TOTAL_OFF) if TOTAL_OFF > 0 else 'N/D')

    # FIX: the BRASIL/OFFSHORE label + value textboxes inherit Calibri
    # (no explicit <a:latin>). Force Gotham SSm Bold on all 4.
    for sh in s4.shapes:
        if sh.name in ('TextBox 454', 'TextBox 458'):       # BRASIL / OFFSHORE labels
            force_font_gotham(sh, size_pt=18, bold=True, color=LIME)
        elif sh.name in ('TextBox 455', 'TextBox 459'):     # R$ / US$ values
            force_font_gotham(sh, size_pt=20, bold=True, color=WHITE)

    # FIX #11: shrink the BRASIL / OFFSHORE header bars (Rectangle 453 + 457)
    # and recentre their child textboxes. Template ships them at H=640_080
    # (~0.7"), which dominates the slide. 460_000 (~0.5") is plenty for
    # 18-20pt text and lets the bar charts below breathe.
    NEW_BAR_H = 460_000
    s4_by_name = {sh.name: sh for sh in s4.shapes}
    for rect_name, lbl_name, val_name in (
        ('Rectangle 453', 'TextBox 454', 'TextBox 455'),
        ('Rectangle 457', 'TextBox 458', 'TextBox 459'),
    ):
        rect = s4_by_name.get(rect_name)
        if rect is None: continue
        rect_top = rect.top
        rect.height = Emu(NEW_BAR_H)
        bar_mid = rect_top + NEW_BAR_H // 2
        lbl = s4_by_name.get(lbl_name)
        val = s4_by_name.get(val_name)
        if lbl is not None:
            lbl.height = Emu(260_000)
            lbl.top = Emu(bar_mid - 130_000)
        if val is not None:
            val.height = Emu(300_000)
            val.top = Emu(bar_mid - 150_000)

    # ── Charts (native API) ──────────────────────────────────────────────────
    # Slide 2 pie + slide 3 bar: 6 categories from slots (non-zero only)
    cats   = [s['name'] for s in slots if s['val'] > 0]
    vals   = tuple(s['val'] for s in slots if s['val'] > 0)
    if cats:
        pie = next(sh.chart for sh in s2.shapes if sh.has_chart)
        cd = CategoryChartData(); cd.categories = cats; cd.add_series('', vals)
        pie.replace_data(cd)
        recolor_chart(pie, PIE_PALETTE)          # FIX #1: rebuild dPt → no stray lime

        bar = next(sh.chart for sh in s3.shapes if sh.has_chart)
        cd2 = CategoryChartData(); cd2.categories = cats; cd2.add_series('', vals)
        bar.replace_data(cd2)
        # Blue gradient palette — DARKEST for the largest bar, LIGHTEST for the
        # smallest. cats come from br_sorted which is DESCENDING (largest at
        # index 0, smallest at the end). So i=0 → DARK, i=n-1 → LIGHT.
        n = len(cats)
        BLUE_DARK  = (32, 60, 92)     # ~ #203c5c — biggest bar
        BLUE_LIGHT = (158, 188, 222)  # ~ #9ebcde — smallest bar
        def _lerp(a, b, t): return int(round(a + (b - a) * t))
        def _hex(rgb): return '{:02X}{:02X}{:02X}'.format(*rgb)
        gradient = []
        for i in range(n):
            t = i / max(1, n - 1)   # largest (i=0) → t=0 → DARK; smallest → t=1 → LIGHT
            gradient.append(_hex(tuple(_lerp(BLUE_DARK[k], BLUE_LIGHT[k], t) for k in range(3))))
        recolor_chart(bar, gradient)
        # FIX #6: bigger axis category labels (the names beside each bar)
        try:
            bar.category_axis.tick_labels.font.size = Pt(12)
            bar.category_axis.tick_labels.font.bold = False
            bar.category_axis.tick_labels.font.name = 'Gotham SSm Black'
        except Exception: pass

    # Slide 4 charts
    s4_charts = sorted([(sh.left, sh.chart) for sh in s4.shapes if sh.has_chart],
                       key=lambda x: x[0])
    if len(s4_charts) >= 2:
        br_chart, off_chart = s4_charts[0][1], s4_charts[1][1]
        # Brasil: list societarias-type items if available, else single bar
        soc_groups = [(n,v) for n,v in br if 'ociet' in n.lower()]
        if soc_groups:
            cd = CategoryChartData()
            cd.categories = [n for n,_ in soc_groups]
            cd.add_series('BR', tuple(v for _,v in soc_groups))
            br_chart.replace_data(cd)
            recolor_chart(br_chart, ['283944'])  # navy
        # Offshore
        if off:
            cd = CategoryChartData()
            cd.categories = [n for n,_ in off]
            cd.add_series('Off', tuple((v if v>0 else 1) for _,v in off))
            off_chart.replace_data(cd)
            recolor_chart(off_chart, ['8E959B'])  # grey
        # FIX #6 (cont'd): bigger axis category labels on both s4 charts
        for ch in (br_chart, off_chart):
            try:
                ch.category_axis.tick_labels.font.size = Pt(12)
                ch.category_axis.tick_labels.font.bold = False
                ch.category_axis.tick_labels.font.name = 'Gotham SSm Black'
            except Exception: pass

    # ── Slide 5: organograma patrimonial — INVERTED LAYOUT ───────────────────
    # Offshore cluster on TOP, person (client) in MIDDLE, Brazilian assets
    # on BOTTOM. Reasoning: visually highlights the international footprint
    # by giving offshore the prominent top position.
    s5 = prs.slides[4]; clear(s5)
    add_title_bar(s5)
    ribbon(s5, "A. ORGANOGRAMA DA ESTRUTURA PATRIMONIAL")
    CX5 = SW//2
    BH = 980_000   # asset-box height (used for both clusters)

    # ─── TOP CLUSTER: Offshore (rendered first, at the top of the slide) ───
    TOP_Y = CT + 30_000  # just below the title ribbon
    if off:
        # OFFSHORE label box (navy block with white text)
        OBW = 2_700_000
        OBH = 360_000
        OBX = CX5 - OBW//2
        OBY = TOP_Y
        R(s5, OBX, OBY, OBW, OBH, fill=NAVY)
        T(s5, "OFFSHORE", OBX, OBY, OBW, OBH,
          pt=13, bold=True, col=WHITE, align='center', font='Gotham SSm Bold')

        # Vertical drop + horizontal distributor below the OFFSHORE box
        OHDIST = OBY + OBH + 110_000
        L(s5, CX5, OBY+OBH, CX5, OHDIST)

        # Offshore asset boxes laid out in a row directly under the label
        n_off = len(off)
        OW = min(3_500_000, (SW-1_000_000)//n_off - 130_000)
        OG = 150_000
        TOW = n_off*OW + (n_off-1)*OG
        OS  = (SW - TOW)//2
        ORT = OHDIST + 55_000
        L(s5, OS+OW//2, OHDIST, OS+TOW-OW//2, OHDIST)
        for i, (name, val) in enumerate(off):
            ox = OS + i*(OW+OG); oy = ORT
            L(s5, ox+OW//2, OHDIST, ox+OW//2, oy)
            sh = R(s5, ox, oy, OW, BH); sh.fill.background()
            sh.line.color.rgb = NAVY; sh.line.width = Pt(0.75)
            icon_for(name)(s5, ox + OW//2, oy + 175_000, sz=210_000, col=NAVY)
            T(s5, name, ox+60_000, oy+330_000, OW-120_000, fh(8.5)*2,
              pt=8.5, bold=True, col=NAVY, align='center', font='Gotham SSm Bold', wrap=True)
            vstr = usd(val) if val > 0 else 'N/D'
            T(s5, vstr, ox+60_000, oy+650_000, OW-120_000, fh(13),
              pt=13, bold=True, col=NAVY, align='center', font='Gotham SSm Bold')
            icon_globe(s5, ox + OW - 130_000, oy + BH - 90_000, sz=170_000, col=NAVY)
        OFF_BOTTOM = ORT + BH
    else:
        OFF_BOTTOM = TOP_Y  # no offshore — person starts higher

    # ─── MIDDLE: client name + person icon ───
    NAME_Y = OFF_BOTTOM + 220_000  # gap between cluster and middle
    T(s5, CLIENT, 1_200_000, NAME_Y, SW-2_400_000, fh(12),
      pt=12, bold=True, col=NAVY, align='center', font='Gotham SSm Bold')
    PERSON_SZ = 300_000
    PERSON_Y = NAME_Y + fh(12) + 100_000
    Person(s5, CX5, PERSON_Y, sz=PERSON_SZ, col=NAVY,
           gender=guess_gender(CLIENT))
    PB = PERSON_Y + PERSON_SZ//2  # bottom edge of the person icon

    # Connector: from offshore cluster down into the person's name area
    if off:
        L(s5, CX5, OFF_BOTTOM, CX5, NAME_Y - 30_000)

    # ─── BOTTOM CLUSTER: Brazilian assets ───
    # Drop from person → BR flag hub
    FLAG_CY = PB + 230_000
    L(s5, CX5, PB+30_000, CX5, FLAG_CY - 105_000)
    brazil_flag(s5, CX5, FLAG_CY, w=300_000)

    LABEL_Y = FLAG_CY + 145_000
    T(s5, "ATIVOS NO BRASIL", CX5-1_500_000, LABEL_Y, 3_000_000, fh(7),
      pt=7, bold=True, col=GRAY_MED, align='center', font='Gotham SSm Bold')

    # Horizontal distributor + BR asset boxes
    HDIST_Y = LABEL_Y + fh(7) + 45_000
    L(s5, CX5, FLAG_CY+90_000, CX5, HDIST_Y)

    br_items = br[:5] if br else []
    n_br = max(1, len(br_items))
    BW = 1_900_000; BG = 80_000
    TBW = n_br*BW + (n_br-1)*BG
    BS  = (SW - TBW)//2
    BRT = HDIST_Y + 55_000

    L(s5, BS+BW//2, HDIST_Y, BS+TBW-BW//2, HDIST_Y)
    for i, (name, val) in enumerate(br_items):
        bx = BS + i*(BW+BG); by = BRT
        L(s5, bx+BW//2, HDIST_Y, bx+BW//2, by)
        sh = R(s5, bx, by, BW, BH); sh.fill.background()
        sh.line.color.rgb = NAVY; sh.line.width = Pt(0.75)
        icon_for(name)(s5, bx + BW//2, by + 175_000, sz=210_000, col=NAVY)
        T(s5, name, bx+60_000, by+330_000, BW-120_000, fh(8.5)*2,
          pt=8.5, bold=True, col=NAVY, align='center', font='Gotham SSm Bold', wrap=True)
        T(s5, brl(val), bx+60_000, by+650_000, BW-120_000, fh(13),
          pt=13, bold=True, col=NAVY, align='center', font='Gotham SSm Bold')
        brazil_flag(s5, bx + BW - 130_000, by + BH - 90_000, w=180_000)

    # ── Slide 6: organograma familiar ────────────────────────────────────────
    s6 = prs.slides[5]; clear(s6)
    add_title_bar(s6)
    ribbon(s6, "B. ORGANOGRAMA DA ESTRUTURA FAMILIAR")
    CX6 = SW//2
    spouse = agg['spouse']
    deps = agg['dependents']
    has_spouse = bool(spouse.get('name'))

    TT = CT+220_000; TW = 3_500_000; TH = 880_000

    if has_spouse:
        # titular left-of-centre, spouse right-of-centre
        GAP = 700_000
        TX = CX6 - TW - GAP//2
        SX = CX6 + GAP//2
        # titular
        sh=R(s6,TX,TT,TW,TH); sh.fill.background()
        sh.line.color.rgb=NAVY; sh.line.width=Pt(0.75)
        Person(s6,TX+TW//2,TT+230_000,sz=260_000,col=NAVY,
               gender=guess_gender(CLIENT))
        T(s6,CLIENT,TX+70_000,TT+420_000,TW-140_000,fh(9),
          pt=9,bold=True,col=NAVY,align='center',font='Gotham SSm Bold',wrap=True)
        # spouse
        sh=R(s6,SX,TT,TW,TH); sh.fill.background()
        sh.line.color.rgb=NAVY; sh.line.width=Pt(0.75)
        Person(s6,SX+TW//2,TT+230_000,sz=260_000,col=NAVY,
               gender=guess_gender(spouse.get('name','')))
        T(s6,spouse['name'],SX+70_000,TT+420_000,TW-140_000,fh(9),
          pt=9,bold=True,col=NAVY,align='center',font='Gotham SSm Bold',wrap=True)
        sub = spouse.get('marriage_regime','')
        if spouse.get('marriage_date'): sub += f" · {spouse['marriage_date']}"
        if sub:
            T(s6,sub,SX+70_000,TT+TH-fh(7)-30_000,TW-140_000,fh(7),
              pt=7,col=GRAY_MED,align='center')
        # connector between them
        L(s6, TX+TW, TT+TH//2, SX, TT+TH//2)
        # children hang from the midpoint between the couple
        FAMILY_CX = CX6
        FAMILY_BOTTOM = TT+TH
    else:
        # solo titular, centred
        TX = CX6 - TW//2
        sh=R(s6,TX,TT,TW,TH); sh.fill.background()
        sh.line.color.rgb=NAVY; sh.line.width=Pt(0.75)
        Person(s6,CX6,TT+230_000,sz=260_000,col=NAVY,
               gender=guess_gender(CLIENT))
        T(s6,CLIENT,TX+70_000,TT+420_000,TW-140_000,fh(9),
          pt=9,bold=True,col=NAVY,align='center',font='Gotham SSm Bold',wrap=True)
        T(s6,"Sem cônjuge declarado",TX+TW+200_000,TT+TH//2-fh(9)//2,
          2_600_000,fh(9),pt=9,col=GRAY_MED)
        FAMILY_CX = CX6
        FAMILY_BOTTOM = TT+TH

    # Dependents row
    if deps:
        L(s6, FAMILY_CX, FAMILY_BOTTOM, FAMILY_CX, FAMILY_BOTTOM+240_000)
        DEP_Y = FAMILY_BOTTOM+240_000
        n_d = len(deps)
        DW = min(2_900_000, (SW-1_400_000)//n_d - 150_000)
        DG = 200_000
        DTOT = n_d*DW + (n_d-1)*DG
        DSx = (SW-DTOT)//2
        DH = 820_000
        L(s6, DSx+DW//2, DEP_Y, DSx+DTOT-DW//2, DEP_Y)
        for i,d in enumerate(deps):
            dx = DSx+i*(DW+DG)
            L(s6, dx+DW//2, DEP_Y, dx+DW//2, DEP_Y+80_000)
            sh=R(s6,dx,DEP_Y+80_000,DW,DH); sh.fill.background()
            sh.line.color.rgb=GRAY_LT; sh.line.width=Pt(0.75)
            Person(s6,dx+DW//2,DEP_Y+80_000+200_000,sz=230_000,col=GRAY_LT,
                   gender=guess_gender(d.get('name','')))
            T(s6,d.get('name','—'),dx+55_000,DEP_Y+80_000+370_000,DW-110_000,fh(8.5),
              pt=8.5,bold=True,col=NAVY,align='center',font='Gotham SSm Bold',wrap=True)
            rel = d.get('relationship','')
            if d.get('birth_date'): rel += f" · {d['birth_date']}"
            T(s6,rel,dx+55_000,DEP_Y+80_000+560_000,DW-110_000,fh(7),
              pt=7,col=GRAY_MED,align='center')
    else:
        L(s6, FAMILY_CX, FAMILY_BOTTOM, FAMILY_CX, FAMILY_BOTTOM+240_000)
        DW=3_000_000; DH=720_000; DX=CX6-DW//2; DY=FAMILY_BOTTOM+240_000
        sh=R(s6,DX,DY,DW,DH); sh.fill.background()
        sh.line.color.rgb=GRAY_LT; sh.line.width=Pt(0.75)
        Person(s6,CX6,DY+220_000,sz=230_000,col=GRAY_LT)
        T(s6,"SEM DEPENDENTES",DX+70_000,DY+400_000,DW-140_000,fh(9),
          pt=9,bold=True,col=GRAY_MED,align='center',font='Gotham SSm Bold')

    # ── Append strategy slides FIRST (índices + slides vazios sketch) ────────
    # We must append BEFORE removing slide 3 — python-pptx auto-numbers new
    # slide files based on the current count. If we remove slide 3 first, the
    # new slide 6 we add will collide with the template's existing slide6.xml,
    # producing two relationships pointing to the same XML file → PowerPoint
    # "needs repair" warning and broken layout.
    indice_p, indice_s, strategy_slides = _append_strategy_slides(prs)

    # ── Now safely remove any extra slides beyond Composição-BR (slide 2)
    # and Composição-Exterior (slide 3). The template has slide 4 etc. that
    # are no longer needed since we restructured the deck. ──────────────────
    # NB: we KEEP slide 3 (was DETALHAMENTO DOS ATIVOS — bar chart) and
    # repurpose it as the Composição Patrimonial — EXTERIOR slide. So slide
    # 3 is NO LONGER removed.

    # ── Redesign slide 2 (Composição — BRASIL) ──────────────────────────────
    s2_new = prs.slides[1]
    _draw_redesigned_slide2(
        s2_new, prs.slide_width, prs.slide_height,
        br, TOTAL_BR,
        indice_p, indice_s, strategy_slides,
        BR_OUTROS_COMPONENTS,
        jurisdiction='Brasil',
    )

    # ── Repurpose slide 3 as Composição — EXTERIOR ──────────────────────────
    s3_new = prs.slides[2]
    OFF_OUTROS_COMPONENTS = agg.get('off_outros_components', {}) or {}
    _draw_redesigned_slide2(
        s3_new, prs.slide_width, prs.slide_height,
        off, TOTAL_OFF,
        indice_p, indice_s, strategy_slides,
        OFF_OUTROS_COMPONENTS,
        jurisdiction='Exterior',
    )

    # ── Remove slide 4 (was PARTICIPAÇÕES SOCIETÁRIAS — twin bar-chart
    # breakdown of BR vs Offshore for Participações). Redundant now that
    # slides 2 (BRASIL) and 3 (EXTERIOR) already present that comparison
    # via the composition donuts. ──────────────────────────────────────────
    sldIdLst = prs.slides._sldIdLst
    ids = list(sldIdLst)
    if len(ids) > 3:
        s4_id_elem = ids[3]
        s4_rId = s4_id_elem.get(
            '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        try:
            s4_part = prs.part.related_part(s4_rId)
        except (KeyError, AttributeError):
            s4_part = None
        sldIdLst.remove(s4_id_elem)
        try:
            prs.part.rels.pop(s4_rId)
        except (KeyError, AttributeError):
            pass
        if s4_part is not None:
            try:
                del prs.part.package._parts[s4_part.partname]
            except (AttributeError, KeyError):
                pass

    # Re-number TextBox 13 (slide number) on every remaining slide
    for slide_num, sl in enumerate(prs.slides, start=1):
        for sh in sl.shapes:
            if sh.name == 'TextBox 13' and hasattr(sh, 'text_frame'):
                for para in sh.text_frame.paragraphs:
                    for run in para.runs:
                        run.text = str(slide_num)
                break

    prs.save(output_path)

    # ── Stage 4: XML post-process (chart fonts + pie color) ──────────────────
    patch_xml(output_path)

    # ── validate ─────────────────────────────────────────────────────────────
    import xml.etree.ElementTree as ET
    with zipfile.ZipFile(output_path,'r') as z:
        bad=[]
        for n in z.namelist():
            if n.endswith('.xml') or n.endswith('.rels'):
                try:
                    with z.open(n) as f: ET.fromstring(f.read())
                except ET.ParseError as e:
                    bad.append((n,str(e)))
        if bad:
            for n,e in bad: print(f"  BAD: {n}: {e}")
            return False
    return True


